// Anfrage lesen (ALLY 20, GET app, Stefan 19.10.2026): Sitzung aus dem Cookie ally_sitzung2 (gleiche Sitzungen wie ALLY 8), Seite und Parameter aus der Adresse.
// Nur geprüfte Werte: seite ^[a-z0-9-]{1,40}$, z = Klappzustände (k:1|0), s = Sortierung (tabelle:spalte:auf|ab), p = Seite einer Tabelle (tabelle:n),
// f = vom Server geöffnetes Fenster (id[:wert]), m = Meldungscode, code = Link "Neues Passwort", bn = geöffnete Benachrichtigung (Zahl; die Datenbank markiert
// nur eigene als gelesen, BA4). Übrige Parameter: Name ^[a-z0-9_]{1,30}$, Wert bis 200 Zeichen ohne Steuerzeichen (tx: Nummernliste bis 10.000), höchstens 20.
// BA11 (Migration 74, Stefan 21.10.2026): eigene Adresse der Oberfläche. traefik setzt X-Oberflaeche-Basis: / nur auf dem Host der Oberfläche (und überschreibt dort einen
// mitgeschickten Wert); ohne diese Kopfzeile wie bisher /webhook/app.
const BASIS = String((($json.headers || {})['x-oberflaeche-basis']) ?? '') === '/' ? '/' : '/webhook/app';
const h = $json.headers || {};
const q = $json.query || {};
const s = v => String((Array.isArray(v) ? v[0] : v) ?? '').trim();
const kekse = String(h.cookie || '').split(';').map(x => x.trim());
const roh = (kekse.find(x => x.startsWith('ally_sitzung2=')) || '').slice('ally_sitzung2='.length);
const token = /^[0-9a-f]{64}$/.test(roh) ? roh : '';
const seite = /^[a-z0-9-]{1,40}$/.test(s(q.seite)) ? s(q.seite) : 'start';
const z = [];
for (const t of s(q.z).split(',').slice(0, 40)) {
  const m = t.match(/^([a-z0-9-]+(?:\.[a-z0-9-]+){1,2}):([01])$/);
  if (m) z.push({ k: m[1], offen: m[2] === '1' });
}
const ms = s(q.s).match(/^([a-z0-9-]{1,40}):([a-z0-9_]{1,40}):(auf|ab)$/);
const mp = s(q.p).match(/^([a-z0-9-]{1,40}):([0-9]{1,5})$/);
const mf = s(q.f).match(/^([a-z0-9-]{1,40})(?::([A-Za-z0-9_-]{1,60}))?$/);
const bn = /^[0-9]{1,18}$/.test(s(q.bn)) ? s(q.bn) : '';
const parameter = {};
let n = 0;
for (const k of Object.keys(q)) {
  if (['seite', 's', 'p', 'z', 'f', 'm', 'code', 'bn', 'einbetten'].includes(k) || !/^[a-z0-9_]{1,30}$/.test(k)) continue;
  const w = s(q[k]);
  // Migration 146 (E4): tx (Export) darf eine Liste von Nummern sein – eigene Grenze 10.000 Zeichen, nur Ziffern und Kommas
  const lang = k === 'tx' && w.length <= 10000 && /^[0-9]{1,9}(,[0-9]{1,9})+$/.test(w);
  if (!w || (w.length > 200 && !lang) || /[\x00-\x1f\x7f]/.test(w)) continue;
  if (++n > 20) break;
  parameter[k] = w;
}
// BA8: Meldung „vergessen“ (Passwort vergessen: Mail mit Link unterwegs)
const meldung = ['falsch', 'gesperrt', 'abgemeldet', 'abgelaufen', 'ungueltig', 'link', 'pwfehler', 'fehler', 'vergessen'].includes(s(q.m)) ? s(q.m) : '';
const code = /^[0-9a-f]{64}$/.test(s(q.code)) ? s(q.code) : '';
return [{ json: { basis: BASIS, token, seite, parameter, seiten: mp ? { [mp[1]]: Number(mp[2]) } : {}, fenster: mf ? { id: mf[1], wert: mf[2] || '' } : null,
  // Ladezeit (Stefan 21.10.2026): einbetten=1 = Rückfall der Seite, weil /stil oder /skript nicht geladen haben (Stil und Skript wieder eingebettet); t0 für Server-Timing
  einbetten: s(q.einbetten) === '1', t0: Date.now(),
  meldung, code, zustand: JSON.stringify(Object.assign({ z }, ms ? { s: { tabelle: ms[1], spalte: ms[2], richtung: ms[3] } } : {}, bn ? { b: bn } : {})) } }];

// Weg bestimmen (ALLY 20): ohne gültige Sitzung bzw. vor dem Festlegen des Passworts -> Anmeldung (ALLY 36); sonst Unterablauf der Seite aus dem Register
// (nur wenn erlaubt und eingerichtet) oder interne Fehlerseite. BA6: Seite „link“ = Weiterleitung zu einem geprüften Link. Der Unterablauf bekommt nur, was er braucht (Sitzung für die Datenbank, Seite, geprüfte Parameter).
const A = $('Anfrage lesen').first().json;
const R = $('Rahmen laden').first().json.r || { angemeldet: false };
const CD = $input.first().json;
// BA11 (Migration 74): auf dem eigenen Host der Oberfläche (Basis /) ohne n8n-Sandbox SameSite=Lax; unter /webhook/app wie bisher None (Seite in der Sandbox)
const keks = (wert, alter) => 'ally_sitzung2=' + wert + '; Path=' + A.basis + '; Max-Age=' + alter + '; HttpOnly; Secure; SameSite=' + (A.basis === '/' ? 'Lax' : 'None');
if (R.angemeldet !== true || R.muss_pw_setzen === true) {
  // Rücksprung nach der Anmeldung: die angefragte Seite (nur Seite und geprüfte Parameter)
  const teile = [];
  // BA8: passwort-vergessen ist wie passwort-neu keine Seite für den Rücksprung
  if (A.seite !== 'start' && A.seite !== 'passwort-neu' && A.seite !== 'passwort-vergessen') teile.push('seite=' + encodeURIComponent(A.seite));
  if (A.seite !== 'passwort-neu' && A.seite !== 'passwort-vergessen') for (const k of Object.keys(A.parameter || {})) teile.push(k + '=' + encodeURIComponent(A.parameter[k]));
  const zurueck = A.basis + (teile.length ? '?' + teile.join('&') : '');
  return [{ json: { weg: 'anmeldung', art: 'seite', basis: A.basis,
    ansicht: R.angemeldet === true ? 'festlegen' : (A.seite === 'passwort-neu' && A.code ? 'neu' : A.seite === 'passwort-vergessen' ? 'vergessen' : 'anmelden'),
    meldung: A.meldung, code: A.code, zurueck: zurueck.length <= 2000 ? zurueck : A.basis, sitzung: R.angemeldet === true ? A.token : '',
    csrf: R.csrf || '', person: R.person || null, hinweis: R.hinweis || null, cd: CD,
    set_cookie: R.angemeldet !== true && A.token ? keks('', 0) : '' } }];
}
// BA6: interne Seite „link“ (Datei der Marke, Entwurf, veröffentlichter Beitrag) -> Prüfung in der Datenbank, dann 303 zum Cloud-Dienst (nur angemeldet)
if (A.seite === 'link') {
  const P = A.parameter || {};
  // BA10 Teil 2 (Migration 70): auch Verbindungen über die vorhandenen Abläufe (li, lis, ig, pf, ki, sa; bei sa der Teilbereich als id, nur Kleinbuchstaben)
  // Migration 75 (Content-Galerie, Stefan 21.10.2026): b = Beitrag eines Talents auf der Plattform (Talent-Profil › Content; Recht prüft talents_planung_link_oeffnen)
  const art = ['kl', 'v', 'd', 'b', 'li', 'lis', 'ig', 'pf', 'ki', 'sa'].includes(String(P.art || '')) ? String(P.art) : '';
  // Stufe 2a (23.10.2026): von=neu = Start aus der neuen Web-App (Einstellungen › Verbindungen); ALLY 12 leitet nach LinkedIn dorthin zurück
  return [{ json: { weg: 'link', sitzung: A.token, art, id: /^[0-9]{1,15}$/.test(String(P.id || '')) || (art === 'sa' && /^[a-z]{2,20}$/.test(String(P.id || ''))) ? String(P.id) : '',
    von: String(P.von || '') === 'neu' ? 'neu' : '', basis: A.basis, set_cookie: keks(A.token, 2592000) } }];
}
// Migration 67: interne Seite „datei“ (Datei aus einem für das Talent freigegebenen Ordner) -> SPEICHER 1 (talent_datei) holt sie, Ally liefert sie als Download aus;
// nie ein Direktlink mit Zugangsdaten. Rechte prüft die Datenbank (nur Talent-Sitzung, nur eigene, nicht beendete Freigaben). o = Freigabe (Ziffern), d = Pfad in der Freigabe.
// BA10 (Migration 69): Seite „datei“ auch für Personen: er = eigenes Ergebnis (z. B. PDF des Kundenüberblicks), kl = Original zu einer offenen Klärung,
// be = Original eines Belegs mit Fehler. Nur die Nummer kommt aus der Adresse; Rechte, Bereich und Pfad prüft die Datenbank (ally_datei_auftrag in „Datei freigeben“).
// BA10 Teil 4 (Stefan 21.10.2026): Downloads, die es bisher nur über ALLY 8 und die daran gebundenen Abläufe gab, über Ally (nie Direktlink):
// mt = Dateien eines Marketing-Themas (md = eine Datei im Themenordner, sonst alle als ZIP; wie ALLY 13), tr = erzeugter Report, ta = Datei der Talents-Ablage
// (wie TALENTS Web), tx = Datenexport eines Talents oder aller (ZIP, wie TALENTS 6); t = Talent-Seite für den Rücksprung. Nur Nummern bzw. der Dateiname im Themenordner
// kommen aus der Adresse; Rechte (Seite erlaubt und dieselbe Prüfung wie ALLY 8), Ablageort und Inhalt kommen aus der Datenbank („Download prüfen“).
// Migration 87 (Stefan 22.10.2026, 13:03): sb = Datei (PDF/CSV) eines erstellten Verkaufsberichts (Rechte und Inhalt aus der Datenbank, shopify_datei_web)
// Monatsberichte (Migration 142, Stefan 24.10.2026): mb = PDF eines Verlauf-Eintrags (Rechte und Pfad aus der Datenbank, monatsbericht_datei_web)
if (A.seite === 'datei' && ['mt', 'tr', 'ta', 'tx', 'sb', 'mb'].some(k => (A.parameter || {})[k] !== undefined)) {
  const P = A.parameter || {};
  const dl = ['mt', 'tr', 'ta', 'tx', 'sb', 'mb'].find(k => P[k] !== undefined);
  const v = String(P[dl] || ''), md = String(P.md || ''), t = String(P.t || '');
  const ok = dl === 'tx' ? (/^([0-9]{1,9}|alle)$/.test(v) || (/^[0-9]{1,9}(,[0-9]{1,9})+$/.test(v) && v.split(',').length <= 1000)) :   // Migration 146 (E4): auch ausgewählte Talents „12,15,20“
   dl === 'ta' || dl === 'sb' || dl === 'mb' ? /^[0-9]{1,15}$/.test(v) : dl === 'tr' ? /^[0-9]{1,12}$/.test(v) : /^[0-9]{1,9}$/.test(v);
  const mdOk = md.length <= 300 && !md.startsWith('/') && !md.includes('\\') && !/[\u0000-\u001f\u007f*?{}]/.test(md) && md.split('/').every(x => x && x !== '.' && x !== '..');
  return [{ json: { weg: 'download', sitzung: A.token, art: dl, id: ok ? v : '', datei: dl === 'mt' && md !== '' && mdOk ? md : '', datei_falsch: dl === 'mt' && md !== '' && !mdOk,
    talent: /^[0-9]{1,9}$/.test(t) ? t : '', basis: A.basis, set_cookie: keks(A.token, 2592000),
    // Migration 196 (Mediakit): ansehen=1 bei ta = PDF im Browser statt Download (Kachel „Mediakit“ zeigt es eingebettet)
    ansehen: dl === 'ta' && String(P.ansehen || '') === '1' } }];
}
if (A.seite === 'datei') {
  const P = A.parameter || {};
  const d = String(P.d || '');
  const quelle = ['er', 'kl', 'be'].find(k => /^[0-9]{1,12}$/.test(String(P[k] || ''))) || '';
  return [{ json: { weg: 'datei', sitzung: A.token, ordner_id: /^[0-9]{1,12}$/.test(String(P.o || '')) ? String(P.o) : '', pfad: d.length <= 1000 && !/[\x00-\x1f\x7f]/.test(d) ? d : '',
    quelle, id: quelle ? String(P[quelle]) : '', basis: A.basis, set_cookie: keks(A.token, 2592000) } }];
}
const F = R.funktion || {};
const ok = F.erlaubt === true && /^[A-Za-z0-9]{1,40}$/.test(String(F.workflow_id || ''));
return [{ json: { weg: ok ? 'funktion' : 'intern', grund: F.erlaubt === true ? 'fehler' : 'fehlt', workflow_id: ok ? String(F.workflow_id) : '',
  sitzung: A.token, seite: F.schluessel || 'start', parameter: A.parameter || {}, seiten: A.seiten || {}, fenster: A.fenster || null,
  funktion: { schluessel: F.schluessel, name: F.name || '', beschreibung: F.beschreibung || '', art: F.art || '', einstellungen_ziel: F.einstellungen_ziel || '', leiste_aktiv: F.leiste_aktiv || '' },
  person: { name: (R.person || {}).name || '', rolle: (R.person || {}).rolle || '' } } }];

// Fehlerinhalt (ALLY 20): Seite gibt es nicht / nicht freigegeben (eine Meldung für beides, verrät nichts) oder Unterablauf nicht verfügbar
// (fehlende bzw. falsche Workflow-ID, Fehler im Unterablauf). Texte aus der Datenbank (ally_ui_texte).
const W = $('Weg bestimmen').first().json;
const T = ($('Rahmen laden').first().json.r || {}).texte || {};
const fehlt = W.weg === 'intern' && W.grund === 'fehlt';
const titel = String(T[fehlt ? 'seite_fehlt_titel' : 'seite_fehler_titel'] || '');
const seite = /^[a-z0-9-]{1,40}$/.test(String(W.seite || '')) ? W.seite : 'start';
return [{ json: { inhalt: { seite: { schluessel: seite, art: 'funktion', titel, krumen: [{ text: String(T.startseite || ''), ziel: { seite: 'start' } }, { text: titel }] },
  bloecke: [{ typ: 'hinweis', ton: 'warn', text: String(T[fehlt ? 'seite_fehlt_text' : 'seite_fehler_text'] || '') },
    { typ: 'aktion', text: String(T.startseite || ''), ziel: { seite: 'start' } }] } } }];

// Notseite (ALLY 20): nur wenn der Baukasten oder die Anmeldung scheitert. Ohne Daten, ohne Corporate Design (das kann die Ursache sein).
// BA11 (Migration 74): Link zur Startseite mit dem Basis-Pfad aus „Anfrage lesen“ (/ bzw. /webhook/app).
const B = $('Anfrage lesen').isExecuted && $('Anfrage lesen').first().json.basis === '/' ? '/' : '/webhook/app';
const html = '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex, nofollow">' +
  '<title>Seite nicht verfügbar</title></head><body><main style="max-width:560px;margin:48px auto;padding:0 16px;font-family:sans-serif;line-height:1.5">' +
  '<h1>Seite nicht verfügbar</h1><p>Diese Seite konnte gerade nicht angezeigt werden. Bitte später noch einmal versuchen.</p>' +
  '<p><a href="' + B + '">Zur Startseite</a></p></main></body></html>';
return [{ json: { html, set_cookie: '' } }];

// Seite zusammensetzen (ALLY 20): Rahmen aus der Datenbank (Kopf, Leiste, Zustände, Texte, Schutzwert), Corporate Design aus CD 1 und Inhalt des Unterablaufs
// zur Seitenbeschreibung für den Baukasten (ALLY 21). Der Unterablauf bestimmt nur den Inhalt: Seitenschlüssel und Parameter setzt der Eingang.
// app: Verweise auf Web-App-Manifest und App-Symbol (GET app/manifest, app/symbol; Stefan 20.10.2026, 09:09).
const A = $('Anfrage lesen').first().json;
const R = $('Rahmen laden').first().json.r || {};
const W = $('Weg bestimmen').first().json;
const CD = $('Corporate Design (CD 1)').first().json;  // Ladezeit: kommt jetzt direkt aus der Datenbank (Knoten gleichen Namens), nicht mehr über den Unterablauf CD 1
const T = R.texte || {};
const istObj = x => !!x && typeof x === 'object' && !Array.isArray(x);
let I = ($input.first().json || {}).inhalt;
if (!istObj(I) || !istObj(I.seite)) {
  const titel = String(T.seite_fehler_titel || '');
  I = { seite: { art: 'funktion', titel, krumen: [{ text: String(T.startseite || ''), ziel: { seite: 'start' } }, { text: titel }] },
    bloecke: [{ typ: 'hinweis', ton: 'warn', text: String(T.seite_fehler_text || '') }] };
}
I.seite.schluessel = W.seite;
I.seite.parameter = Object.assign({}, A.parameter || {});
// Migration 77 (Stefan 21.10.2026): Seitenzahl (?p=<Block>:<n>) auch für den Baukasten, damit lange Listen auf der eigenen Seite „Alle anzeigen“ blättern
I.seite.seiten = istObj(A.seiten) ? A.seiten : {};
if (W.funktion && W.funktion.leiste_aktiv) I.seite.leiste_aktiv = W.funktion.leiste_aktiv;
// Migration 181 (Stefan 30.10.2026): Satz am i-Symbol des Seitentitels (seite.info), wofür die Seite da ist; höchstens 20 Wörter, keine Fachwörter.
// Alle Seiten des Basispakets und des Social-Media-Pakets; die graue Zeile darunter bleibt. Fehlerseiten bekommen keinen Satz.
// Der Satz steht allein in seite.seiten_info (die Web-App zeigt nur ihn am Titel). seite.info bleibt, wie es war (ALLY 24/25/26: Hinweis auf Testdaten, in der
// Web-App nicht am Titel; Prüfung M181 M1); nur wo es leer ist, bekommt es den Satz für die bisherige Oberfläche (ALLY 21 zeigt seite.info am Titel).
// Liste und Begründung: docs/m181_umbenennungen.md (werkzeuge/m181/texte.py).
const INFO181 = {"start": "Hier siehst du auf einen Blick, was neu ist, und kommst zu allen Funktionen, die du nutzen darfst.",
  "benachrichtigungen": "Hier findest du alle Hinweise von {produkt} an dich und kommst mit einem Klick zur passenden Stelle.",
  "fragen": "Stelle {produkt} hier eine Frage oder gib einen Auftrag, wenn du den Chat nicht öffnen willst.",
  "mail-assistent": "Hier siehst du, wie {produkt} neue Mails eingeordnet hat, und findest Vorschläge für Antworten.",
  "system-mails": "Hier fasst {produkt} technische Meldungen aus den Postfächern zusammen, zum Beispiel zu Backups und Updates.",
  "kalender": "Hier siehst du deine Termine, trägst neue ein und änderst oder löschst sie.",
  "projektbudgets": "Hier siehst du, wie viel Budget laufende Projekte aus Papierkram schon verbraucht haben.",
  "ki-verbrauch": "Hier siehst du, was die KI in diesem Monat gekostet hat und wofür.",
  "e-profil": "Hier änderst du deinen Namen, deine Anmeldung und dein Passwort, auch das für den Chat.",
  "e-benachrichtigungen": "Lege fest, welche Hinweise bei dir in der Glocke erscheinen.",
  "e-kalender": "Hier holst du Termine und Deadlines aus {produkt} in deine eigene Kalender-App.",
  "e-startseite": "Lege fest, welche Seite du nach der Anmeldung zuerst siehst und wie sie aussieht.",
  "e-speicherorte": "Hier legst du fest, wo {produkt} Dateien ablegt und wie groß Downloads für Talents sein dürfen.",
  "e-postfaecher": "Hier bindest du die Postfächer der Firma ein und legst fest, wer sie sieht.",
  "e-systemnachrichten": "Lege fest, über welches Postfach {produkt} Einladungen, Erinnerungen und neue Passwörter verschickt.",
  "e-regeln": "Lege fest, dass Mails eines Absenders immer gleich eingeordnet werden, ohne dass die KI entscheidet.",
  "e-unternehmen": "Hier pflegst du Name, Farben, Schrift und Logos der Firma, mit denen {produkt} Seiten und PDFs gestaltet.",
  "e-personen": "Hier lädst du Personen ein, gibst ihnen eine Rolle und sperrst bei Bedarf ihren Zugang.",
  "e-rollen": "Hier legst du fest, was jede Rolle in {produkt} sehen und tun darf.",
  "e-pakete": "Hier siehst du, welche Pakete gebucht sind und welche Funktionen dazugehören.",
  "e-paket": "Hier schaltest du die Funktionen dieses Pakets ein oder aus.",
  "e-ki": "Hier legst du fest, wie viel die KI im Monat kosten darf und wer den Verbrauch sieht.",
  "e-mail-assistent": "Hier legst du fest, mit welchem Namen und aus welchem Postfach {produkt} Entwürfe für dich schreibt.",
  "e-vertrag": "Hier legst du fest, welche Pakete im Vertrag dieser Firma stehen.",
  "e-admins": "Hier legst du fest, wer Admin oder Superadmin ist.",
  "e-chat": "Hier siehst du, welche Chat-Zugänge angelegt sind und ob dabei etwas hängt.",
  "e-preise": "Hier pflegst du Preise und Zugang der KI und siehst die echten Kosten im Monat.",
  "e-plattform-apps": "Hier richtest du die Apps ein, über die Talents ihre Accounts bei Instagram, TikTok und anderen verbinden.",
  "e-adressen": "Hier legst du fest, unter welcher Adresse {produkt} im Internet erreichbar ist.",
  "e-testdaten": "Hier schaltest du Beispieldaten zum Ausprobieren ein oder aus.",
  "talents": "Hier siehst du, wie sich deine Talents entwickeln und was gerade zu tun ist.",
  "talents-import": "Lege viele Talents auf einmal aus einer Tabelle an, jedes mit eigenem Einladungslink.",
  "talents-anfrage": "Füge die Anfrage einer Marke ein, und {produkt} schlägt dir passende Talents vor.",
  "talents-texte": "Hier lässt du Texte für Mails an Marken oder Talents vorschreiben und bearbeitest sie.",
  "talent": "Alles zu einem Talent: Zahlen, Beiträge, Aufgaben und Kampagnen, zum Beispiel vor einem Gespräch mit Talent oder Marke.",
  "talent-einstellungen": "Hier verbindest du Accounts und legst fest, was das Talent in seinem Bereich sieht.",
  "talent-zahlen": "Lade Bilder oder Dateien mit Zahlen hoch, wenn ein Account nicht verbunden ist.",
  "talent-konzept": "Hier legst du Ziele und Themen des Talents fest und siehst, ob es auf Kurs ist.",
  "talent-wf": "Zeigt, welche Beiträge beim Talent besser laufen als sonst, damit du mehr davon planen kannst.",
  "talent-marken": "Lass {produkt} Marken suchen, die zu diesem Talent passen könnten.",
  "talent-mails": "Hier findest du alle Mails mit diesem Talent und deine Entwürfe an einer Stelle.",
  "talent-texte": "Hier lässt du Texte für dieses Talent vorschreiben, zum Beispiel für Mails an Marken.",
  "talent-beitrag": "Zeigt die Zahlen eines einzelnen Beitrags und wie sie sich mit der Zeit entwickeln.",
  "kampagnen": "Hier planst du Kampagnen mit Marken und siehst, welche Beiträge wann fällig sind.",
  "kampagne": "Alles zu einer Kampagne: was die Marke will, wer was liefert und bis wann.",
  "kampagne-zuordnen": "Lege fest, welche Beiträge zu dieser Kampagne zählen, damit die Zahlen im Bericht stimmen.",
  "talent-reports": "Hier erstellst du Berichte als PDF, einmalig oder regelmäßig, zum Weitergeben an Marken oder Talents.",
  "briefings": "Hier lässt du die Zahlen deiner Talents von der KI auswerten, einmalig oder nach Zeitplan.",
  "briefing": "Hier stellst du ein, was diese Analyse auswertet, wann und für wen, und liest ihre Ergebnisse.",
  "talent-bereich": "Hier siehst du deine Aufgaben, Termine und Zahlen und verbindest deine Accounts.",
  "e-talents": "Grundregeln für alle Talents: Einladungen, Löschen, Warnungen, KI-Funktionen und wo Dateien abgelegt werden.",
  "e-kampagnen": "Hier legst du fest, wann {produkt} an Deadlines erinnert und in welcher Währung Beträge stehen.",
  "e-talent-reports": "Hier schaltest du ein, welche Hinweise zu deinen Talents du bekommst, zum Beispiel im Chat.",
  "papierkorb": "Hier holst du Gelöschtes zurück oder löschst es endgültig."};
const info181 = (s, P) => {
