  return `Bei ${d} ist ein Fehler aufgetreten${code ? ' (Fehler ' + code + ')' : ''}.${spaeter}`;
}

// Monatsbericht-Ergebnis (ALLY 20, BA5, wie ALLY 8 "Bericht-Ergebnis aufbereiten"): kurzer Hinweis und die Eckdaten (oder der genaue Grund) einmalig in der Sitzung.
// Die Seite Monatsbericht (ALLY 31) liest das Ergebnis (art = monatsbericht) und zeigt es im Abschnitt "Letzter Bericht".
const F = $('Formular lesen').first().json;
const auftrag = ((($('Aktion ausführen').first().json || {}).r || {}).r) || {};
const r = $input.first().json || {};
const fehlerText = e => String((e && (e.message || e.description)) || e || '').replace(/\s*\[line \d+\]\s*$/, '').trim();
let text, art, ergebnis;
// Migration 136: Nummer des Monatsberichts (Seite Monatsberichte) und Monat für den Verlauf; ohne Nummer (alte Seite) wie bisher
const mb = /^[0-9]{1,18}$/.test(String(auftrag.bericht_id || '')) ? { bericht_id: String(auftrag.bericht_id), monat: String(r.monat || auftrag.monat || '') } : {};
if (r.ok === true) {
  text = 'Bericht erstellt: ' + r.titel + ' für ' + r.kunde + ' · ' + r.projekt + '.'; art = 'ok';
  ergebnis = { art: 'monatsbericht', ok: true, titel: r.titel, kunde: r.kunde, projekt: r.projekt, datei: r.datei, ablage: r.ablage, zeitraum: r.zeitraum,
    eintraege: r.eintraege, zeit: r.zeit, stunden: r.stunden, betrag: r.betrag, aufgaben_dl: r.aufgaben_dl || '', preis: r.preis,
    verbraucht_bisher: r.verbraucht_bisher || '', rest: r.rest || '', ueber_budget: !!r.ueber_budget, ...mb };
} else {
  // Stefan 24.10.2026, 12:20: Meldungen auf Deutsch – technische Texte (englisch aus n8n) werden übersetzt, der Rohtext bleibt nur intern (technik)
  const roh = fehlerText(r.error) || fehlerText(r.fehler);
  const grund = !roh ? 'Unbekannter Fehler. Bitte später erneut versuchen.' : fdIstTechnisch(roh) ? fehlerDeutsch('', r.error || r.fehler) : roh;
  text = 'Bericht nicht erstellt: ' + grund; art = 'fehler';
  ergebnis = { art: 'monatsbericht', ok: false, label: String(auftrag.label || ''), grund, ...(roh && roh !== grund ? { technik: roh.slice(0, 500) } : {}), ...mb };
}
return [{ json: { token: F.sitzung, text, art, ergebnis: JSON.stringify(ergebnis) } }];

// Link weiterleiten (ALLY 20, BA6): 303 zum Link aus der Datenbank (talents_planung_link_oeffnen prüft Zugriff und gibt nur https-Links zurück),
// sonst zurück zu den Kampagnen mit Meldung. Hier noch einmal: nur https, keine Steuerzeichen.
const W = $('Weg bestimmen').first().json;
const r = ($input.first().json || {}).r || {};
const url = String(r.url || '');
const ok = r.ok === true && /^https:\/\/[A-Za-z0-9.-]{3,253}(:[0-9]{1,5})?([\/?#][^\s<>"]*)?$/.test(url) && url.length <= 2000;
// BA10 Teil 2 (Migration 70): Verbindungen (LinkedIn, Instagram, Postfach-Zugang, KI-Zugang, Superadmin) laufen über die vorhandenen Abläufe der bisherigen Oberfläche;
// dafür gilt dieselbe Sitzung (gleiche Tabelle) auch als Cookie der bisherigen Oberfläche (Pfad /webhook/web). Zugangsdaten werden hier nicht berührt.
const VB = ['li', 'lis', 'ig', 'pf', 'ki', 'sa'].includes(String(W.art || ''));
const ally8 = ok && VB && r.ally8 === true && /^[0-9a-f]{64}$/.test(String(W.sitzung || ''));
// BA10 Teil 4 (Stefan 21.10.2026): „Mit LinkedIn verbinden“ (li, lis) mit von=app, damit ALLY 12 nach LinkedIn hierher zurückleitet (ALLY 12 prüft den Wert gegen seine Liste).
// Stufe 2a: von=neu aus der neuen Web-App (sonst wie bisher app)
const mitVon = ally8 && (W.art === 'li' || W.art === 'lis') ? url + (url.includes('?') ? '&' : '?') + 'von=' + (W.von === 'neu' ? 'neu' : 'app') : url;
// Migration 75: Beitrag eines Talents (b) ohne Recht oder ohne gültigen Link -> zurück zu den Talents mit Meldung (statt zu den Kampagnen)
return [{ json: { ziel: ok ? mitVon : W.basis + (VB ? '?seite=einstellungen&m=fehler' : W.art === 'b' ? '?seite=talents&m=fehler' : '?seite=kampagnen&m=fehler'),
  set_cookie: ally8 ? 'ally_sitzung=' + W.sitzung + '; Path=/webhook/web; Max-Age=2592000; HttpOnly; Secure; SameSite=None' : (W.set_cookie || '') } }];

// Zahlen-Auftrag (ALLY 20, BA7, Migration 62): Datei aus dem Formular des Talent-Bereichs (POST app/datei, Feld "datei") mit dem Vorschlag aus der Datenbank
// (talent_selbst_zahlen_vorschlag, Talent-ID aus der Sitzung) an "TALENTS Zahlen auslesen" (wie das Hochladen auf der Talent-Seite: vorschlag schon angelegt).
const r = (($('Aktion ausführen').first().json || {}).r || {}).r || {};
let bin = null;
try {
  const w = $('Datei').first();
  const b = (w && w.binary) || {};
  const k = Object.keys(b).find(x => x === 'datei') || Object.keys(b).find(x => x.startsWith('datei'));
  if (k) bin = b[k];
} catch (e) { bin = null; }
// BA10 Teil 4 (Stefan 21.10.2026): beim Hochladen durch die Agentur (tm_hochladen) die Person wie TALENTS Web („Datei weitergeben“) für den KI-Verbrauch; beim Talent leer wie bisher
const nutzer = String((($('Aktion ausführen').first().json || {}).r || {}).nutzer || '');
const aus = { json: { quelle: 'hochladen', nutzer, vorschlag: r, datei_name: String((bin && bin.fileName) || '').slice(0, 120) } };
if (bin) aus.binary = { datei: bin };
return [aus];

// Versand-Ergebnis (ALLY 20, BA8): Rückgabe von ALLY 39 (Zugangsdaten „Systemnachrichten – Versand (SMTP)“ gesetzt, geprüft bzw. geleert) für die Datenbank
// (ally_systemnachricht_absender_abschliessen). Nie das Passwort. Ohne Antwort von ALLY 39 ein ehrlicher Fehlertext; eingerichtet wird dann nichts.
const F = $('Formular lesen').first().json;
const R = (($('Aktion ausführen').first().json || {}).r || {}).r || {};
const j = $input.first().json || {};
const t = v => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, 300);
let e;
if (j.error || !j.modus) e = { modus: String(R.modus || ''), fehler: 'Die Prüfung hat nicht geantwortet' + (j.error ? ': ' + t(j.error.message || j.error) : '') + '.' };
else e = { modus: t(j.modus), patch_status: t(j.patch_status), patch_meldung: t(j.patch_meldung), test_status: j.test_status === 'OK' ? 'OK' : t(j.test_status), test_meldung: t(j.test_meldung), fehler: t(j.fehler) };
// Migration 86: bei „Versand einrichten“ je Postfach zusätzlich Aktion, Platz und die geprüften Angaben (aus der Datenbank, nie das Passwort) für postfach_versand_abschliessen
if (/^pf_versand_/.test(String(F.aktion || ''))) Object.assign(e, { aktion: String(F.aktion), platz: String(R.platz ?? ''), host: t(R.host), port: String(R.port ?? ''), benutzer: t(R.benutzer) });
return [{ json: { token: F.sitzung, ergebnis: JSON.stringify(e) } }];

parameters.query:
-- Versand abschließen (ALLY 20): Absender für Systemnachrichten (BA8) bzw. Versand je Postfach (Migration 86, pf_versand_*)
SELECT CASE WHEN coalesce(($2::jsonb)->>'aktion', '') LIKE 'pf\_versand\_%' THEN postfach_versand_abschliessen($1::text, $2::jsonb)
            ELSE ally_systemnachricht_absender_abschliessen($1::text, $2::jsonb) END AS r;

parameters.jsCode:
// Speicherort-Auftrag (ALLY 20, Migration 66, Stefan 20.10.2026): eigener Speicherort wie in ALLY 8 über ALLY 11 (Formular „web/speicherort“).
// ALLY 11 prüft Sitzung, Admin, Paket, Adresse, Ordner, Schreiben und Löschen, setzt erst dann die Zugangsdaten in n8n und setzt die Meldung für die nächste Seite.
// Aufruf intern (localhost) mit derselben Sitzung (ally_web_sitzungen gilt für beide Oberflächen) und der eigenen Adresse als Host und Herkunft.
// Herkunft, Schutzwert, Sitzung und Admin sind vorher geprüft („Formular lesen“, „Aktion ausführen“). Die Felder kommen erst hier aus dem Formular: das Passwort
// geht nur an ALLY 11, nie in die Datenbank (auch nicht in „daten“); ALLY 20 und ALLY 11 speichern keine Ausführungsdaten. Kein Nachbau von ALLY 11.
const F = $('Formular lesen').first().json;
const R = (($('Aktion ausführen').first().json || {}).r || {}).r || {};
const A = $('Aktion').isExecuted ? ($('Aktion').first().json || {}) : {};
const b = A.body || {};
const s = v => String((Array.isArray(v) ? v[0] : v) ?? '').trim();
const kurz = (v, max) => s(v).replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, ' ').slice(0, max);
const host = String((A.headers || {}).host || '').trim().toLowerCase();
const aktion = ['speichern', 'server', 'belege_ordner', 'verbinden'].includes(R.aktion) ? R.aktion : '';
// Migration 89: Passwort nur bei „Verbindung prüfen“ (sp_ort_verbinden) und beim Ändern des Zugangs (sp_ort_speichern); das Umstellen mit dem gewählten Ordner schickt keines.
const mitPw = (aktion === 'speichern' && F.aktion === 'sp_ort_speichern') || (aktion === 'verbinden' && F.aktion === 'sp_ort_verbinden');
return [{ json: {
  url: 'http://localhost:5678/webhook/web/speicherort',
  kopf: { Host: /^[a-z0-9.-]{1,253}$/.test(host) ? host : 'ungueltig', Origin: 'https://' + host, Cookie: 'ally_sitzung=' + (/^[0-9a-f]{64}$/.test(String(F.sitzung || '')) ? F.sitzung : '') },
  body: { aktion, name: kurz(b.name, 61), adresse: kurz(b.adresse, 300).toLowerCase(), benutzer: kurz(b.benutzer, 201), ordner: kurz(b.ordner, 300), ordner_belege: kurz(b.ordner_belege, 300),
    passwort: mitPw ? String((Array.isArray(b.passwort) ? b.passwort[0] : b.passwort) ?? '').slice(0, 501) : '' } } }];

// Speicherort-Ergebnis (ALLY 20, Migration 66): ALLY 11 antwortet mit einer Weiterleitung (303). Führt sie zur Seite Speicherort bzw. Belege, hat ALLY 11 die Meldung
// schon gesetzt (Erfolg oder verständlicher Fehler). Sonst (keine Antwort, Herkunft abgelehnt, Sitzung abgelaufen) ein ehrlicher Fehlertext. Nie das Passwort.
const F = $('Formular lesen').first().json;
const j = $input.first().json || {};
const kopf = (h, k) => { h = h || {}; const f = Object.keys(h).find(x => x.toLowerCase() === k); return f ? String(h[f]) : ''; };
const st = Number(j.statusCode) || 0, ort = kopf(j.headers, 'location');
const ursache = j.error ? ' (' + String(j.error.message || j.error).replace(/\s+/g, ' ').slice(0, 120) + ')' : '';
let fehler = '';
if (st !== 303 && st !== 302) fehler = 'Der Speicherort konnte gerade nicht geprüft werden' + ursache + '. Es wurde nichts geändert. Bitte später noch einmal versuchen.';
else if (/[?&]m=abgelaufen/.test(ort)) fehler = 'Die Anmeldung ist abgelaufen. Es wurde nichts geändert. Bitte neu anmelden.';
else if (!/[?&]ansicht=(speicherort|belege)/.test(ort)) fehler = 'Die Prüfung des Speicherorts wurde abgelehnt. Es wurde nichts geändert. Bitte die Seite neu laden.';
return [{ json: { token: F.sitzung, fehler } }];

// Datei-Auftrag (ALLY 20, Migration 67): Auftrag talent_datei für SPEICHER 1 aus „Weg bestimmen“ (Seite „datei“). Ohne Freigabe-ID: SPEICHER 1 lehnt ab.
// BA10 (Migration 69): er / kl / be (Personen) – Auftrag „holen“ aus der Datenbank („Datei freigeben“, ally_datei_auftrag). Ohne Freigabe ein leerer Pfad:
// SPEICHER 1 lehnt dann ab, ohne etwas zu lesen; die Meldung kommt aus der Datenbank.
const W = $('Weg bestimmen').first().json;
if (W.quelle) {
  const f = ($input.first().json || {}).f || {};
  const a = f.ok === true && f.auftrag ? f.auftrag : {};
  return [{ json: { aktion: 'holen', bereich: String(a.bereich || 'ally'), pfad: String(a.pfad || '') } }];
}
return [{ json: { aktion: 'talent_datei', token: W.sitzung || '', daten: { ordner_id: W.ordner_id || '', pfad: W.pfad || '' } } }];

// Datei bereitstellen (ALLY 20, Migration 67): Ergebnis von SPEICHER 1 (talent_datei). Mit Datei: Download (immer als Anhang, Typ application/octet-stream,
// damit der Browser nichts aus dem Speicherort als Seite öffnet); Dateiname ASCII-Ersatz plus UTF-8-Name nach RFC 6266/8187. Ohne Datei: 303 zurück in den
// Talent-Bereich (Abschnitt Ordner); die Meldung hat SPEICHER 1 gesetzt.
// BA10 (Migration 69): er / kl / be (Personen): Dateiname aus der Datenbank; ohne Datei 303 zurück auf die Seite aus der Datenbank, Meldung über „Datei-Meldung“.
const W = $('Weg bestimmen').first().json;
const e = $input.first() || {};
const j = e.json || {};
const bin = e.binary && e.binary.datei;
const f = W.quelle ? ((($('Datei freigeben').first() || {}).json || {}).f || {}) : {};
if (j.ok === true && bin) {
  const name = String((W.quelle ? f.name : j.name) || bin.fileName || 'datei').replace(/[\x00-\x1f\x7f"\\\/]/g, '_').slice(0, 200) || 'datei';
  const ascii = name.normalize('NFKD').replace(/[^\x20-\x7e]/g, '').replace(/[%;]/g, '_') || 'datei';
  const utf8 = encodeURIComponent(name).replace(/['()*]/g, c => '%' + c.charCodeAt(0).toString(16).toUpperCase());
  return [{ json: { da: true, disposition: 'attachment; filename="' + ascii + '"; filename*=UTF-8\'\'' + utf8, set_cookie: W.set_cookie || '' }, binary: { datei: bin } }];
}
if (W.quelle) {
  const z = String(f.zurueck || '');
  const meldung = f.ok === true ? 'Die Datei konnte nicht geholt werden: ' + String(j.fehler || 'unbekannter Fehler').slice(0, 300)
    : f.angemeldet === false ? '' : String(f.meldung || 'Diese Datei ist nicht verfügbar.');
  return [{ json: { da: false, ziel: W.basis + (/^\?seite=[a-z0-9-]{1,40}(#a-[a-z0-9-]{1,40})?$/.test(z) ? z : ''), set_cookie: W.set_cookie || '', sitzung: W.sitzung || '', meldung } }];
}
const zurueck = W.basis + '?seite=talent-bereich' + (W.ordner_id ? '&to=' + encodeURIComponent(W.ordner_id) : '') + '#a-ordner';
return [{ json: { da: false, ziel: zurueck, set_cookie: W.set_cookie || '', sitzung: '', meldung: '' } }];

// Speicher-Auftrag (ALLY 20, Migration 67): nach so_anlegen / so_umbenennen (Datenbank: weiter = speicher) den Ordner-Auftrag für SPEICHER 1 bauen.
// Migration 89: bereich ablage (Ordner-Browser unter Einstellungen › Speicherorte, so_ablageordner) wird wie berichte durchgereicht.
// Nur bekannte Aktionen, Sitzung aus "Formular lesen"; SPEICHER 1 prüft Recht, Pfad und Name noch einmal (speicher_ordner_auftrag) und setzt die Meldung.
const F = $('Formular lesen').first().json;
const r = (($('Aktion ausführen').first().json || {}).r || {}).r || {};
const aktion = ['ordner_anlegen', 'ordner_umbenennen'].includes(String(r.aktion || '')) ? String(r.aktion) : '';
const d = r.daten && typeof r.daten === 'object' ? r.daten : {};
return [{ json: { aktion, token: F.sitzung || '', daten: Object.assign({ pfad: String(d.pfad ?? '').slice(0, 1000), name: String(d.name ?? '').slice(0, 130) }, ['berichte', 'ablage'].includes(d.bereich) ? { bereich: d.bereich } : {}) } }];

// Beleg-Auftrag (ALLY 20, BA10, Migration 69): Datei aus dem Formular „Beleg hochladen“ (POST app/datei, Feld "datei") mit dem Auftrag aus der Datenbank
// (ally_luecken_ui_aktion: Pfad im Eingang der Belege wie bei ALLY 3, Kennung, Name). Die Datei hängt nur als Verweis am Eintrag; „Beleg als PDF“ liest sie.
const r = (($('Aktion ausführen').first().json || {}).r || {}).r || {};
let bin = null;
try {
  const w = $('Datei').first();
  const b = (w && w.binary) || {};
  const k = Object.keys(b).find(x => x === 'datei') || Object.keys(b).find(x => x.startsWith('datei'));
  if (k) bin = b[k];
} catch (e) { bin = null; }
const aus = { json: { pfad: String(r.pfad || ''), typ: String(r.typ || ''), bild: r.bild === true } };
if (bin) aus.binary = { datei: bin };
return [aus];

// Beleg als PDF (ALLY 20, BA10, Migration 69): Auftrag „ablegen“ für SPEICHER 1 (Bereich ally, nicht überschreiben). PDF und E-Rechnung (XML) unverändert,
// nach kurzer Prüfung des Inhalts (PDF beginnt mit %PDF, XML mit <). Fotos (JPG, PNG, WEBP) werden über den internen Render-Dienst ally-render (Gotenberg, wie ALLY 7)
// zu einem PDF (eine A4-Seite). Ohne gültige Datei: leerer Pfad (SPEICHER 1 legt nichts ab) und ein Fehlertext für „Beleg eintragen“.
const it = $input.first() || {};
const j = it.json || {};
const bin = it.binary && it.binary.datei;
const pfad = String(j.pfad || '');
const nein = fehler => [{ json: { aktion: 'ablegen', bereich: 'ally', pfad: '', ueberschreiben: false, vorfehler: fehler } }];
if (!pfad || !bin) return nein('Es ist keine Datei angekommen. Bitte erneut hochladen.');
const name = pfad.split('/').pop();
const buf = await this.helpers.getBinaryDataBuffer(0, 'datei');
const auftrag = { aktion: 'ablegen', bereich: 'ally', pfad, ueberschreiben: false, vorfehler: '' };
if (!j.bild) {
  const kopf = buf.subarray(0, 1024).toString('latin1').replace(/^\xef\xbb\xbf/, '').trimStart();
  if (pfad.endsWith('.pdf') && !kopf.startsWith('%PDF')) return nein('Die Datei ist kein lesbares PDF.');
  if (pfad.endsWith('.xml') && !kopf.startsWith('<')) return nein('Die Datei ist keine lesbare E-Rechnung (XML).');
  return [{ json: auftrag, binary: { datei: await this.helpers.prepareBinaryData(buf, name, pfad.endsWith('.xml') ? 'application/xml' : 'application/pdf') } }];
}
// Foto -> PDF (Multipart als reiner ASCII-Text wie in ALLY 7; das Bild steckt als Base64 im HTML)
const RENDER = 'http://ally-render:3000';
const html = '<!doctype html><html><head><meta charset="utf-8"><style>@page { size: A4; margin: 10mm; } html, body { margin: 0; } '
  + 'img { display: block; max-width: 100%; max-height: 270mm; margin: 0 auto; }</style></head><body><img src="data:' + String(j.typ || 'image/jpeg').replace(/[^a-z\/]/g, '')
  + ';base64,' + buf.toString('base64') + '" alt="Beleg"></body></html>';
const grenze = '----ally' + Date.now().toString(16) + Math.random().toString(16).slice(2);
const felder = { preferCssPageSize: 'true', printBackground: 'true' };
let body = '';
for (const [k, v] of Object.entries(felder)) body += '--' + grenze + '\r\nContent-Disposition: form-data; name="' + k + '"\r\n\r\n' + v + '\r\n';
body += '--' + grenze + '\r\nContent-Disposition: form-data; name="files"; filename="index.html"\r\nContent-Type: text/html\r\n\r\n' + html + '\r\n--' + grenze + '--\r\n';
try {
  const antwort = await this.helpers.httpRequest({ method: 'POST', url: RENDER + '/forms/chromium/convert/html', body,
    headers: { 'Content-Type': 'multipart/form-data; boundary=' + grenze }, encoding: 'arraybuffer', json: false, timeout: 90000, returnFullResponse: true, ignoreHttpStatusErrors: true });
  const pdf = Buffer.from(antwort.body);
  if (antwort.statusCode !== 200 || !pdf.subarray(0, 4).toString('latin1').startsWith('%PDF')) return nein('Das Foto konnte nicht in ein PDF umgewandelt werden (Render-Dienst ' + antwort.statusCode + ').');
  return [{ json: auftrag, binary: { datei: await this.helpers.prepareBinaryData(pdf, name, 'application/pdf') } }];
} catch (e) {
  return nein('Das Foto konnte nicht in ein PDF umgewandelt werden: ' + String(e.message || e).slice(0, 200));
}

// Werkzeug-Felder (ALLY 20, BA10 Teil 3, Migration 71, Stefan 20.10.2026): ergänzt „Formular lesen“, ohne es zu ändern. Felder der letzten Aktionen aus ALLY 8
// (gleiche Namen und Grenzen wie dort): KI-Werkzeuge der Talents (kz_*, wf_erstellen, tx_*, ma_starten, ms_*, me_anlegen), KI-Funktionen und Speicherort der Talents
// (kf_speichern, ab_*), Verfolgung eines Beitrags (tb_verfolgung), Superadmin (sa_meta_app, sa_meta_ig, sa_plattform_app, sa_meta_rechte), Einrichtungen
// (ki_zugang, pk_zugang, pf_*, li_*), Instagram-Zugang (instagram), Tabellen als Datei (ti_csv); cd_gestaltung zusätzlich mit der Auswahl der Icons.
// Geheimnisse (Schlüssel, Passwörter, App-Geheimcodes) kommen NIE in „daten“: „Aktion ausführen“ bzw. die Einrichtungs-Knoten lesen sie selbst aus dem Webhook.
// Alle anderen Aktionen: unverändert weiter. Prüfen, Rechte und Texte macht die Datenbank (ally_ui_werkzeug_aktion bzw. die vorhandenen Aktionen).
const F = $input.first().json;
const AKT = F.aktion;
const KI_FN = { kz: ['angaben_speichern', 'erstellen', 'ueberarbeitung_anfordern', 'entwurf_speichern', 'aktivieren', 'verwerfen', 'ziel_speichern', 'ziel_loeschen'], wf: ['erstellen'],
  tx: ['erstellen', 'speichern', 'loeschen'], ma: ['starten'], ms: ['kriterium_hinzufuegen', 'kriterium_entfernen', 'suche_starten', 'bewerten', 'bewertung_zuruecknehmen'], me: ['anlegen'],
  kf: ['speichern'], ab: ['waehlen', 'dienst_speichern', 'dienst_entfernen', 'ordner_zuruecksetzen'] };
const kiFn = String(AKT || '').slice(0, 2), kiAk = String(AKT || '').slice(3);
const istKi = /^[a-z]{2}_[a-z_]{1,40}$/.test(String(AKT || '')) && (KI_FN[kiFn] || []).includes(kiAk);
const ANDERE = ['tb_verfolgung', 'sa_meta_app', 'sa_meta_ig', 'sa_plattform_app', 'sa_meta_rechte', 'ki_zugang', 'pk_zugang', 'pf_zugang_speichern', 'pf_zugang_pruefen', 'pf_platz_freigeben',
  'li_app', 'li_trennen', 'li_seite_app', 'li_seite_trennen', 'instagram', 'ti_csv', 'cd_gestaltung'];
if (!istKi && !ANDERE.includes(AKT)) return [{ json: F }];
const b = ($('Aktion').isExecuted ? ($('Aktion').first().json || {}).body : null) || {};
const s = v => String((Array.isArray(v) ? v[0] : v) ?? '').trim();
const liste = v => (Array.isArray(v) ? v : (v === undefined || v === null || v === '' ? [] : [v])).map(x => String(x).trim());
const id9 = v => /^[0-9]{1,9}$/.test(s(v)) ? s(v) : '';
