// Ohne feste Werte (17.10.2026): Bevorzugt wird die Facebook-Seite mit dem Namen des eigenen Unternehmens (Einstellungen › Unternehmen), sonst die erste mit Instagram-Konto.
const FIRMA = String($('Recht prüfen (Instagram)').first().json.firma || '').trim();
