const hole = async (pfad, qs) => {
  const r = await this.helpers.httpRequest({ method: 'GET', url: G + pfad, qs, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
  let b = r.body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) {} }
