// Download-Plan (ALLY 20, BA10 Teil 4, Stefan 21.10.2026): Weg wie in ALLY 8 bzw. den daran gebundenen Abläufen, nie ein Direktlink:
// speicher = eine Datei über SPEICHER 1 holen (Datei eines Themas, Report), ablage = Datei der Talents-Ablage über TALENTS Ablage, thema = alle Dateien eines Themas
// als ZIP (Knoten aus ALLY 13), export = Datenexport als ZIP (Knoten aus TALENTS 6); sonst zurück auf die Seite mit Meldung (über „Datei-Meldung“).
const W = $('Weg bestimmen').first().json;
const r = ($input.first().json || {}).r;
const B = W.basis;
const zur = { mt: W.id ? '?seite=marketing&thema=' + W.id : '?seite=marketing',
  tr: W.talent ? '?seite=talent&id=' + W.talent + '#a-reports' : '?seite=talent-reports#a-berichte',
  ta: W.talent ? '?seite=talent&id=' + W.talent + '&w=mails#a-dateien' : '?seite=talents',
  tx: /^[0-9]{1,9}$/.test(W.id) ? '?seite=talent&id=' + W.id : '?seite=talents',
  sb: /^[0-9]{1,9}$/.test(String((r && r.bericht) || '')) ? '?seite=verkaufsberichte&bericht=' + r.bericht : '?seite=verkaufsberichte',
  mb: /^[0-9]{1,18}$/.test(String((r && r.bericht) || '')) ? '?seite=monatsbericht&bericht=' + r.bericht : '?seite=monatsbericht' }[W.art] || '';
const basis = { ziel: B + zur, set_cookie: W.set_cookie || '', sitzung: W.sitzung || '' };
const zurueck = (meldung, ziel) => [{ json: Object.assign({ weg: 'fehler', da: false }, basis, { meldung: String(meldung || '').slice(0, 300) }, ziel ? { ziel } : {}) }];
// Keine Personen-Sitzung (z. B. Talent) oder abgelaufen: ohne Meldung zur Startseite (die Anmeldung prüft ALLY 20 dort wie immer)
if (!r || typeof r !== 'object' || r.angemeldet === false) return zurueck('', B);
if (W.datei_falsch) return zurueck('Diese Datei gibt es nicht.');
if (r.ok !== true || !W.id) return zurueck(r.recht === false ? 'Diese Datei ist für dich nicht freigeschaltet.'
  : r.fehler ? r.fehler : W.art === 'mt' ? 'Zu diesem Thema gibt es keine Dateien.' : 'Diese Datei ist nicht verfügbar.');
if (W.art === 'mt' && W.datei) return [{ json: Object.assign({ weg: 'speicher', name: W.datei.split('/').pop(), auftrag: { aktion: 'holen', bereich: 'ally', pfad: String(r.ordner) + '/' + W.datei } }, basis) }];
if (W.art === 'mt') return [{ json: Object.assign({ weg: 'thema' }, basis) }];
if (W.art === 'tr') return [{ json: Object.assign({ weg: 'speicher', name: String(r.datei || 'report.pdf'), auftrag: { aktion: 'holen', bereich: 'ally', pfad: String(r.pfad || '') } }, basis) }];
// Migration 196 (Mediakit): ta mit ansehen = PDF zum Ansehen (nur echtes PDF, „Download bereitstellen“), einbetten = darf in einem Rahmen derselben Oberfläche stehen
if (W.art === 'ta') return [{ json: Object.assign({ weg: 'ablage', name: String(r.name || 'datei'), auftrag: { aktion: 'holen', datei_id: Number(r.datei_id) } },
  W.ansehen === true ? { ansehen: true, einbetten: true } : {}, basis) }];
// Migration 87: Verkaufsbericht – Datei aus der Datenbank (base64), PDF zum Ansehen im Browser, CSV zum Herunterladen
if (W.art === 'sb') return [{ json: Object.assign({ weg: 'db', name: String(r.name || 'Verkaufsbericht'), mime: r.mime === 'text/csv' ? 'text/csv' : 'application/pdf', b64: String(r.b64 || '') }, basis) }];
// Migration 142: PDF eines Monatsberichts über SPEICHER 1 (Pfad nur aus der Datenbank), zum Ansehen im Browser
if (W.art === 'mb') return [{ json: Object.assign({ weg: 'speicher', name: String(r.name || 'Monatsbericht.pdf'), ansehen: true,
  auftrag: { aktion: 'holen', bereich: 'ally', pfad: String(r.pfad || '') } }, basis) }];
return [{ json: Object.assign({ weg: 'export', token: W.sitzung, talent: W.id }, basis) }];

// Download bereitstellen (ALLY 20, BA10 Teil 4, Stefan 21.10.2026): Ergebnis von SPEICHER 1 bzw. TALENTS Ablage (ok und Binärdaten „datei“). Mit Datei: Download als Anhang
// wie „Datei bereitstellen“ (application/octet-stream über „Datei ausgeben“, Dateiname ASCII plus UTF-8 nach RFC 6266/8187); ohne Datei zurück mit Meldung („Datei-Meldung“).
const PL = $('Download-Plan').first().json;
const e = $input.first() || {}, j = e.json || {}, bin = e.binary && e.binary.datei;
if (j.ok === true && bin) {
  const name = String(PL.name || bin.fileName || 'datei').replace(/[\x00-\x1f\x7f"\\\/]/g, '_').slice(0, 200) || 'datei';
  const ascii = name.normalize('NFKD').replace(/[^\x20-\x7e]/g, '').replace(/[%;]/g, '_') || 'datei';
  const utf8 = encodeURIComponent(name).replace(/['()*]/g, c => '%' + c.charCodeAt(0).toString(16).toUpperCase());
  // Migration 142: Monatsbericht-PDF zum Ansehen (neuer Tab) – nur wenn der Inhalt wirklich ein PDF ist; sonst wie bisher als Anhang
  if (PL.ansehen === true) {
    // Prüfung 142 (2b): Lesen der Datei kann scheitern – dann die bestehende deutsche Meldung statt eines Abbruchs ohne Antwort
    let kopf = '';
    try { kopf = (await this.helpers.getBinaryDataBuffer(0, 'datei')).subarray(0, 5).toString('latin1'); } catch (x) { kopf = null; }
    if (kopf === null) return [{ json: { da: false, ziel: PL.ziel, set_cookie: PL.set_cookie || '', sitzung: PL.sitzung || '',
      meldung: 'Das PDF konnte gerade nicht aus dem Speicherort geholt werden. Bitte später erneut versuchen; wurde der Kundenordner umbenannt, den Bericht neu erstellen.' } }];
    if (kopf === '%PDF-') return [{ json: { da: true, typ: 'application/pdf', disposition: 'inline; filename="' + ascii + '"; filename*=UTF-8\'\'' + utf8, set_cookie: PL.set_cookie || '', einbetten: PL.einbetten === true },
      binary: { datei: Object.assign({}, bin, { mimeType: 'application/pdf' }) } }];
  }
  return [{ json: { da: true, disposition: 'attachment; filename="' + ascii + '"; filename*=UTF-8\'\'' + utf8, set_cookie: PL.set_cookie || '' }, binary: { datei: bin } }];
}
return [{ json: { da: false, ziel: PL.ziel, set_cookie: PL.set_cookie || '', sitzung: PL.sitzung || '',
  // Migration 142: beim Monatsbericht-PDF eine deutsche Meldung ohne technische Angaben des Speicherorts
  meldung: PL.ansehen === true ? 'Das PDF konnte gerade nicht aus dem Speicherort geholt werden. Bitte später erneut versuchen; wurde der Kundenordner umbenannt, den Bericht neu erstellen.'
    : 'Die Datei konnte nicht geholt werden' + (j.fehler ? ': ' + String(j.fehler).slice(0, 300) : '.') } }];

// Download-Fehler (ALLY 20, BA10 Teil 4): ZIP eines Themas bzw. Datenexport nicht möglich (Fehlertext aus den Knoten von ALLY 13 bzw. TALENTS 6) -> zurück auf die Seite mit Meldung.
const PL = $('Download-Plan').first().json;
const f = String(($input.first().json || {}).fehler || '').trim();
return [{ json: { da: false, ziel: PL.ziel, set_cookie: PL.set_cookie || '', sitzung: PL.sitzung || '', meldung: (f || 'Der Download hat nicht geklappt.').slice(0, 300) } }];

// Themenordner auflisten (erste Ebene)
const o = $('Download prüfen').isExecuted ? ($('Download prüfen').first().json.r || {}).ordner : (($json.auftrag || {}).ordner);
return [{ json: { aktion: 'liste', bereich: 'ally', pfad: String(o || '') } }];

// Unterordner des Themenordners auflisten (zweite Ebene). Ohne Unterordner noch einmal die erste Ebene, damit der Ablauf weiterläuft.
const w = $input.first().json || {};
const unter = (w.eintraege || []).filter(e => e.ordner && !String(e.name).startsWith('.'));
return (unter.length ? unter : [null]).map(e => ({ json: { aktion: 'liste', bereich: 'ally', pfad: e ? w.pfad + '/' + e.name : w.pfad } }));

// Alle Dateien des Themenordners (erste und zweite Ebene) mit Pfad relativ zum Themenordner
const w = $('Ordner lesen (SPEICHER 1)').first().json || {};
const basis = String(w.pfad || '');
const liste = [];
if (w.ok === true) for (const e of w.eintraege || []) if (!e.ordner && !String(e.name).startsWith('.')) liste.push({ pfad: e.name, ordner: '', name: e.name, bytes: e.bytes });
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.ok !== true || j.pfad === basis) continue;
  const unter = String(j.pfad).slice(basis.length + 1);
  for (const e of j.eintraege || []) if (!e.ordner && !String(e.name).startsWith('.')) liste.push({ pfad: unter + '/' + e.name, ordner: unter, name: e.name, bytes: e.bytes });
}
liste.sort((a, b) => (a.ordner || '').localeCompare(b.ordner || '') || a.name.localeCompare(b.name, 'de', { numeric: true }));
const fehler = w.ok === true ? '' : (w.fehler || 'Der Themenordner konnte nicht gelesen werden.');
if (fehler || !liste.length) return [{ json: { leer: true, fehler: fehler || 'Im Themenordner liegen keine Dateien.' } }];
const r = $('Download prüfen').first().json.r || {};
return liste.map(x => ({ json: { aktion: 'holen', bereich: 'ally', pfad: r.ordner + '/' + x.pfad, rel: x.pfad } }));

// Alle geholten Dateien in ein Item (Felder f0, f1, …), Dateiname im ZIP = Pfad im Themenordner
const A = $('Holen-Aufträge').all();
const binary = {}; const fehlt = [];
$input.all().forEach((it, i) => { const b = it.binary && it.binary.datei; if (it.json && it.json.ok === true && b) binary['f' + i] = { ...b, fileName: (A[i] && A[i].json.rel) || b.fileName }; else fehlt.push((A[i] && A[i].json.rel) || ('Datei ' + (i + 1))); });
const r = $('Download prüfen').first().json.r || {};
const slug = String(r.titel || 'beitrag').toLowerCase().replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'beitrag';
if (!Object.keys(binary).length) return [{ json: { leer: true, fehler: 'Die Dateien konnten nicht geholt werden.' } }];
return [{ json: { felder: Object.keys(binary).join(','), name: 'thema-' + r.thema + '_' + slug + '.zip', fehlt }, binary }];

// Export: Seiten planen (Stefan 18.10.2026). Eingang: Ergebnis von talents_export_start($token, $talent) als json.r.
// Ausgang: je Teil und Seite ein Eintrag für talents_export_teil; bei Fehler ein Eintrag mit fehler (Antwort ohne Datei).
const r = $input.first().json.r || {};
if (r.ok !== true) return [{ json: { ok: false, angemeldet: r.angemeldet === true, fehler: String(r.fehler || 'Der Export ist nicht möglich.') } }];
// Migration 146 (E4): den Umfang für talents_export_teil liefert die Datenbank (teil_umfang: Talent, „alle“ oder die geprüften Nummern der Auswahl)
const talent = r.umfang === 'auswahl' ? String(r.teil_umfang || '') : r.umfang === 'talent' ? String(r.talent_id) : 'alle';
if (r.umfang === 'auswahl' && !/^[0-9]{1,9}(,[0-9]{1,9})*$/.test(talent)) return [{ json: { ok: false, angemeldet: true, fehler: 'Der Export ist nicht möglich. Bitte die Seite neu laden.' } }];
const out = [];
for (const t of Array.isArray(r.teile) ? r.teile : []) {
  const seiten = Math.max(1, Number(t.seiten) || 1);
  for (let s = 1; s <= seiten; s++) out.push({ json: { ok: true, talent, teil: String(t.teil), seite: s } });
}
return out;

// Export: CSV-Dateien und LIESMICH.txt bauen (Stefan 18.10.2026). Format wie talents_csv in der Datenbank:
// UTF-8 mit BOM, Trennzeichen Semikolon, jedes Feld in Anführungszeichen, "" für ", Zeilenende CRLF;
// Texte, die mit = + - @ beginnen und keine Zahl sind, bekommen ein vorangestelltes ' (Schutz vor Formeln).
// Eingang: alle Ergebnisse von talents_export_teil (json.r) und der Plan aus "Export starten" (json.r von talents_export_start).
const plan = $('Export starten').first().json.r;
const feld = v => {
  let s = v === null || v === undefined ? '' : (typeof v === 'object' ? JSON.stringify(v) : String(v));
  if (/^[=+@-]/.test(s) && !/^-?[0-9]+(\.[0-9]+)?$/.test(s)) s = "'" + s;
  return '"' + s.split('"').join('""') + '"';
};
const teile = {};
for (const it of $input.all()) {
  const r = it.json.r || {};
  if (r.ok !== true) throw new Error('Export: ' + String(r.fehler || 'Teil nicht lesbar').slice(0, 200));
  const t = teile[r.teil] = teile[r.teil] || { datei: r.datei, spalten: r.spalten, seiten: {} };
  t.seiten[r.seite] = r.zeilen || [];
}
const dateien = [];
for (const p of plan.teile) {
  const t = teile[p.teil] || { datei: p.datei, spalten: p.spalten.map(s => s.name), seiten: {} };
  const zeilen = [];
  for (const s of Object.keys(t.seiten).map(Number).sort((a, b) => a - b)) zeilen.push(...t.seiten[s]);
  if (zeilen.length !== Number(p.anzahl)) throw new Error('Export: ' + p.datei + ' hat ' + zeilen.length + ' statt ' + p.anzahl + ' Zeilen. Bitte erneut exportieren.');
  const text = '﻿' + [t.spalten.map(feld).join(';')].concat(zeilen.map(z => z.map(feld).join(';'))).join('\r\n') + '\r\n';
  dateien.push({ name: p.datei, text });
}
dateien.push({ name: plan.beschreibung_datei, text: '﻿' + plan.beschreibung });
// je Datei ein Binäreintrag (für den Knoten "Compression", zip)
return [{ json: { dateiname: plan.dateiname, anzahl: dateien.length },
  binary: Object.fromEntries(dateien.map((d, i) => ['datei_' + i, { data: Buffer.from(d.text, 'utf8').toString('base64'), mimeType: d.name.endsWith('.txt') ? 'text/plain' : 'text/csv', fileName: d.name }])) }];

// Datei-Angaben (ALLY 20, BA10 Teil 4, Stefan 21.10.2026): nur für „Zahlen per Screenshot“ durch die Agentur (tm_hochladen, Datenimport im Talent-Profil): Art, Größe
// und Name der Datei wie TALENTS Web („Anfrage lesen“), damit die Datenbank sie prüfen kann. Alle anderen Anfragen laufen unverändert weiter (gleicher Eintrag, gleiche Datei).
const it = $input.first();
const b = (it.json || {}).body || {};
if (String((Array.isArray(b.aktion) ? b.aktion[0] : b.aktion) ?? '').trim() !== 'tm_hochladen') return [it];
const s = v => String(Array.isArray(v) ? (v[0] ?? '') : (v ?? '')).replace(/[\x00-\x1f\x7f]/g, ' ').trim().slice(0, 300);
const bin = it.binary || {};
const k = Object.keys(bin).find(x => x === 'datei') || Object.keys(bin).find(x => x.startsWith('datei'));
let angaben = { datei_groesse: '0' };
if (k) {
  const buf = await this.helpers.getBinaryDataBuffer(0, k);
  const name = s(bin[k].fileName).slice(0, 120);
  let typ = String(bin[k].mimeType || '').toLowerCase().split(';')[0].trim();
  const ende = (name.split('.').pop() || '').toLowerCase();
  if (typ === 'image/jpg') typ = 'image/jpeg';
  if (!typ || typ === 'application/octet-stream' || typ === 'text/plain') typ = { csv: 'text/csv', txt: 'text/plain', json: 'application/json', pdf: 'application/pdf', png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp' }[ende] || typ;
  angaben = { datei_name: name, datei_typ: typ, datei_groesse: String(buf.length), binaer: k };
}
return [{ json: Object.assign({}, it.json, { tm_datei: angaben }), binary: it.binary }];

// Datenimport-Felder (ALLY 20, BA10 Teil 4, Stefan 21.10.2026): ergänzt „Formular lesen“ und „Werkzeug-Felder“, ohne sie zu ändern. Felder für „Zahlen per Screenshot“
// durch die Agentur (Datenimport im Talent-Profil) mit denselben Namen und Grenzen wie TALENTS Web („Anfrage lesen“, Zahlen ohne Verbindung): tm_hochladen (talent_id,
// Art/Größe/Name der Datei aus „Datei-Angaben“), tm_bestaetigen und tm_verwerfen (vorschlag_id, n<Nr>_ja/_wert/_von/_bis), tm_wert_neu, tm_wert_loeschen. Alle anderen Aktionen unverändert.
const F = $input.first().json;
if (!['tm_hochladen', 'tm_bestaetigen', 'tm_verwerfen', 'tm_wert_neu', 'tm_wert_loeschen'].includes(F.aktion)) return [{ json: F }];
const W = $('Aktion').isExecuted ? $('Aktion').first().json : $('Datei').isExecuted ? $('Datei').first().json : {};
const b = (W || {}).body || {};
const s = v => String(Array.isArray(v) ? (v[0] ?? '') : (v ?? '')).replace(/[\x00-\x1f\x7f]/g, ' ').trim().slice(0, 300);
const daten = {};
for (const [k, v] of Object.entries(b)) if (/^(n[0-9]{1,2}_(ja|wert|von|bis)|vorschlag_id|wert_id|talent_id|plattform|kennzahl|wert|von|bis|konto)$/.test(k)) daten[k] = s(v);
if (F.aktion === 'tm_hochladen') Object.assign(daten, ($('Datei-Angaben').isExecuted ? ($('Datei-Angaben').first().json || {}).tm_datei : null) || { datei_groesse: '0' });
return [{ json: Object.assign({}, F, { daten, daten_text: JSON.stringify(daten) }) }];

// Felder Runde 2 (ALLY 20, Stefan 21.10.2026): ergänzt „Formular lesen“, ohne es zu ändern (Muster wie „Datenimport-Felder“).
