//    kunde_id, projekt_id, monat, aufgaben_dl; Name und Kunde des Projekts prüft danach „Projekt übernehmen“ in Papierkram), mb_papierkorb und mb_erstellen (bericht_id, monat), mb_wiederherstellen (element = mb:<id>),
//    mb_loeschen (elemente = mb:/mv:, anzahl), mb_lauf_papierkorb (bericht_id, laeufe = Nummern der Verlauf-Einträge, anzahl). Rechte prüft die Datenbank (monatsbericht_ui_aktion); erstellt wird wie bisher über BERICHT 2.
const F = $input.first().json;
if (/^mb_[a-z_]{1,30}$/.test(String(F.aktion || ''))) {
  const W1 = $('Aktion').isExecuted ? $('Aktion').first().json : {};
