  const els = (Array.isArray(b1.elemente) ? b1.elemente : b1.elemente === undefined ? [] : [b1.elemente]).map(x => String(x).trim()).filter(x => /^m[bv]:[0-9]{1,18}$/.test(x)).slice(0, 1000);
  const laeufe = (Array.isArray(b1.laeufe) ? b1.laeufe : b1.laeufe === undefined ? [] : [b1.laeufe]).map(x => String(x).trim()).filter(x => /^[0-9]{1,18}$/.test(x)).slice(0, 1000);
  const daten = { bericht_id: nr(b1.bericht_id, 18), teil: ['projekt', 'monat', 'optionen'].includes(s1(b1.teil)) ? s1(b1.teil) : '', kunde_id: nr(b1.kunde_id, 12), projekt_id: nr(b1.projekt_id, 12),
    monat: /^20[0-9]{2}-(0[1-9]|1[0-2])$/.test(s1(b1.monat)) ? s1(b1.monat) : '',
    aufgaben_dl: s1(b1.aufgaben_dl) === 'ja' ? 'ja' : '', element: /^m[bv]:[0-9]{1,18}$/.test(s1(b1.element)) ? s1(b1.element) : '', elemente: els, laeufe, anzahl: nr(b1.anzahl, 4) };
  return [{ json: Object.assign({}, F, { daten, daten_text: JSON.stringify(daten) }) }];
}
const TD = /^td_[a-z_]{1,20}$/.test(String(F.aktion || ''));
const RP = ['regel_wiederherstellen', 'regel_endgueltig', 'regel_papierkorb_leeren', 'unternehmen_wiederherstellen', 'unternehmen_endgueltig', 'unternehmen_papierkorb_leeren',
  'kp_regel_wiederherstellen', 'kp_regel_endgueltig', 'kp_regel_papierkorb_leeren', 'tr_vorlage_wiederherstellen', 'tr_vorlage_endgueltig', 'tr_vorlage_papierkorb_leeren',
  'kp_papierkorb_wiederherstellen', 'kp_papierkorb_endgueltig', 'kp_papierkorb_leeren',
  'mk_papierkorb_wiederherstellen', 'mk_papierkorb_endgueltig', 'mk_papierkorb_leeren', 'mk_papierkorb_entfernen',
  'tp_papierkorb_wiederherstellen', 'tp_papierkorb_endgueltig', 'tp_papierkorb_leeren'].includes(F.aktion);
// 12. Migration 147 (Stefan 24.10.2026, Konzept D): eigene Liste „Meine Talents“ – tl_liste_hinzu, tl_liste_entfernen (ids = markierte Talents, Ziffern mit Komma,
//    höchstens 1000) wie tl_papierkorb_leeren. Rechte prüft die Datenbank (talents_liste_aktion: nur sichtbare Talents, die Liste gibt keine Rechte).
const TL = ['tl_papierkorb_leeren', 'tl_liste_hinzu', 'tl_liste_entfernen'].includes(F.aktion);
const RO = ['ro_endgueltig', 'ro_papierkorb_leeren'].includes(F.aktion);
if (!TD && !RP && !RO && !TL && !['start_anordnen', 'postfach'].includes(F.aktion)) return [{ json: F }];
const W = $('Aktion').isExecuted ? $('Aktion').first().json : {};
const b = (W || {}).body || {};
const s = v => String((Array.isArray(v) ? v[0] : v) ?? '').trim();
if (RP) {
  const daten = /_papierkorb_leeren$/.test(F.aktion) ? { ids: /^[0-9]{1,18}(,[0-9]{1,18}){0,999}$/.test(s(b.ids)) ? s(b.ids) : '' } : { id: /^[0-9]{1,18}$/.test(s(b.id)) ? s(b.id) : '' };
  return [{ json: Object.assign({}, F, { daten, daten_text: JSON.stringify(daten) }) }];
}
if (TL) {
  // Migration 147 (Prüfung N2): bei tl_liste_* mehr als 1000 Nummern nicht leeren, damit die Datenbank „höchstens 1.000“ meldet (Grenze 20.000 Zeichen)
  const daten = { ids: /^[0-9]{1,9}(,[0-9]{1,9}){0,999}$/.test(s(b.ids)) || (F.aktion !== 'tl_papierkorb_leeren' && s(b.ids).length <= 20000 && /^[0-9]{1,9}(,[0-9]{1,9})*$/.test(s(b.ids))) ? s(b.ids) : '',
    bestaetigung: s(b.bestaetigung).slice(0, 300) };
  return [{ json: Object.assign({}, F, { daten, daten_text: JSON.stringify(daten) }) }];
}
if (RO) {
  const daten = F.aktion === 'ro_papierkorb_leeren' ? { liste: /^[a-z0-9_]{1,40}(,[a-z0-9_]{1,40}){0,999}$/.test(s(b.liste)) ? s(b.liste) : '' }
    : { schluessel: /^[a-z0-9_]{1,40}$/.test(s(b.schluessel)) ? s(b.schluessel) : '' };
  return [{ json: Object.assign({}, F, { daten, daten_text: JSON.stringify(daten) }) }];
}
if (TD) {
  // Migration 168 (Bauplan B7): ohne td_passwort (keine Test-Logins mehr)
  const daten = { groesse: /^[0-9]{1,3}$/.test(s(b.groesse)) ? s(b.groesse) : '', aus: s(b.aus) === '1' ? '1' : '0' };
  return [{ json: Object.assign({}, F, { daten, daten_text: JSON.stringify(daten) }) }];
}
if (F.aktion === 'postfach') return [{ json: String((Array.isArray(b.signatur_html) ? b.signatur_html[0] : b.signatur_html) ?? '').length > 20000 ? Object.assign({}, F, { aktion: 'ungueltig' }) : F }];
const liste = (v, re, max) => (Array.isArray(v) ? v : (v === undefined || v === null || v === '' ? [] : [v])).map(x => String(x).trim()).filter(x => re.test(x)).slice(0, max);
const daten = Object.assign({}, F.daten || {});
if (b.gruppen !== undefined) daten.gruppen = liste(b.gruppen, /^[a-z0-9-]{1,40}$/, 30);
const gs = s(b.gruppe_schieben).slice(0, 60);
if (gs) daten.gruppe_schieben = gs;
if (b.ub_reihe !== undefined) { daten.ub_reihe = liste(b.ub_reihe, /^[a-z0-9-]{1,40}$/, 40); daten.ub_sichtbar = liste(b.ub_sichtbar, /^[a-z0-9-]{1,40}$/, 40); }
const us = s(b.ub_schieben).slice(0, 60);
if (us) daten.ub_schieben = us;
return [{ json: Object.assign({}, F, { daten, daten_text: JSON.stringify(daten) }) }];

