// App-Fassung (ALLY 20, Runde 2, Stefan 21.10.2026 – Safari zeigte noch „D“): ergänzt „Seite zusammensetzen“ um rahmen.app.version für ?v= an icon und
// apple-touch-icon. Eigenes Symbol: p + Prüfsumme (aus „Rahmen laden“, app_v); sonst c + kurzer Wert aus Bildmarke, Farben und Name. So lädt Safari nach jeder
// Änderung des Symbols die neue Datei statt eines zwischengespeicherten Bildes.
const j = $input.first().json;
if (!j || !j.rahmen || !j.rahmen.app) return [{ json: j }];
const R = $('Rahmen laden').first().json || {};
const CD = $('Corporate Design (CD 1)').first().json || {};
const v = String(R.app_v || '');
let version;
if (/^[0-9a-f]{12}$/.test(v)) version = 'p' + v;
else {
  const L = CD.logos || {}, F = CD.farben || {};
  const s = String(L.bildmarke_fuer_hell || '') + '|' + String(L.bildmarke_fuer_dunkel || '') + '|' + String(F.hell || '') + '|' + String(F.dunkel || '') + '|' + String((R.r || {}).produkt || '');
  let x = 2166136261; for (let i = 0; i < s.length; i++) { x ^= s.charCodeAt(i); x = Math.imul(x, 16777619) >>> 0; }
  version = 'c' + x.toString(16).padStart(8, '0');
}
j.rahmen.app = Object.assign({}, j.rahmen.app, { version });
return [{ json: j }];

// PNG-Bildmarke (ALLY 20, Runde 2, Stefan 21.10.2026): ergänzt „App-Datei bauen“. Ohne eigenes App-Symbol, aber mit quadratischer PNG-Bildmarke (mind. 180 Pixel)
// wird diese direkt als PNG geliefert, weil Safari ein SVG nicht als Symbol für Dock und Home-Bildschirm nutzt (dann erscheint der Anfangsbuchstabe).
// Im Manifest stehen die Symbol-Adressen zusätzlich mit ?v= (bzw. &v=), damit Änderungen sofort ankommen. Mit eigenem Symbol und ohne passende PNG-Bildmarke unverändert.
const it = $input.first();
const A = $('App-Anfrage').first().json || {};
const D = $('App-Daten laden').first().json || {};
const CD = $('App-CD (CD 1)').first().json || {};
const B64 = /^[A-Za-z0-9+/]+={0,2}$/;
const S = D.symbol && typeof D.symbol === 'object' && B64.test(String(D.symbol.png_b64 || '')) && Number(D.symbol.breite) >= 512 && Number(D.symbol.breite) === Number(D.symbol.hoehe);
if (S) return [it];
const L = CD.logos || {}, Fb = CD.farben || {};
const png = b => { try { const m = /^data:image\/png;base64,(.*)$/.exec(String(b || '')); if (!m || !B64.test(m[1])) return null; const buf = Buffer.from(m[1], 'base64');
  if (buf.length < 24 || buf.readUInt32BE(12) !== 0x49484452) return null; return { b64: m[1], w: buf.readUInt32BE(16), h: buf.readUInt32BE(20) }; } catch (x) { return null; } };
let PB = null; for (const k of ['bildmarke_fuer_hell', 'bildmarke_fuer_dunkel']) { const p = png(L[k]); if (p) { PB = p.w >= 180 && p.w === p.h ? p : null; break; } }
const farbe = n => /^#[0-9a-fA-F]{6}$/.test(String(Fb[n] || '')) ? String(Fb[n]).toUpperCase() : '';
const name = String(D.name || '').replace(/\s+/g, ' ').trim().slice(0, 45);
let fv = 2166136261; { const s = String(L.bildmarke_fuer_hell || '') + '|' + String(L.bildmarke_fuer_dunkel || '') + '|' + (farbe('hell') || '#FFFFFF') + '|' + farbe('dunkel') + '|' + name;
  for (let i = 0; i < s.length; i++) { fv ^= s.charCodeAt(i); fv = Math.imul(fv, 16777619) >>> 0; } }
const CV = 'c' + fv.toString(16).padStart(8, '0');
const PFAD = A.basis === '/' ? '' : '/webhook/app';
if (A.art === 'manifest') {
  let m; try { m = JSON.parse((await this.helpers.getBinaryDataBuffer(0, 'datei')).toString('utf8')); } catch (x) { return [it]; }
  m.icons = PB ? [{ src: PFAD + '/symbol?v=' + CV, sizes: PB.w + 'x' + PB.h, type: 'image/png', purpose: 'any' }]
    : (m.icons || []).map(i => Object.assign({}, i, { src: String(i.src || '') + (String(i.src || '').includes('?') ? '&' : '?') + 'v=' + CV }));
  const body = Buffer.from(JSON.stringify(m), 'utf8').toString('base64');
  return [{ json: Object.assign({}, it.json, { bytes: Buffer.from(body, 'base64').length }), binary: { datei: { data: body, mimeType: it.binary.datei.mimeType, fileName: it.binary.datei.fileName } } }];
}
if (!PB) return [it];
return [{ json: Object.assign({}, it.json, { typ: 'image/png', bytes: Buffer.from(PB.b64, 'base64').length }), binary: { datei: { data: PB.b64, mimeType: 'image/png', fileName: 'symbol.png' } } }];

