-- Begrüßung laden (ALLY 20, BA10, Migration 69): nach erfolgreichem Anlegen eines Chat-Benutzers für ein Talent die Begrüßung (talent_chat_begruessung);
-- nur für den eben erledigten Auftrag dieses Aufrufs (höchstens 10 Minuten alt) und nur, wenn der Chat-Benutzer beim Talent-Zugang eingetragen ist. Sonst NULL.
SELECT CASE WHEN $2::text = 'true' AND $1::text ~ '^[0-9]{1,18}$' THEN (SELECT talent_chat_begruessung(a.ref_id, a.matrix_user_id) FROM ally_chat_auftraege a
  JOIN talent_zugaenge z ON z.talent_id = a.ref_id AND z.matrix_user_id = a.matrix_user_id
  WHERE a.id = $1::bigint AND a.art = 'anlegen' AND a.ref_art = 'talent' AND a.status = 'erledigt' AND a.erledigt_am > now() - interval '10 minutes') END AS b;

parameters.jsCode:
// Corporate Design (ALLY 20, Ladezeit Stefan 21.10.2026): wertet das CD aus „CD aus der Datenbank“ aus, mit denselben Regeln und derselben Ausgabe wie der
// Unterablauf CD 1 („Corporate Design auswerten“), damit Seite, Anmeldung (ALLY 36) und App-Fassung unverändert weiterlaufen. Der Name bleibt, weil andere
// Knoten ihn lesen. Unterschied: keine Icon-Bibliothek (braucht die Oberfläche nicht). t_rahmen = Zeitpunkt für Server-Timing.
// Ist ein CD hinterlegt, aber unvollständig oder ungültig, bricht der Ablauf mit klarer Meldung ab (kein stiller Ersatz). Ohne CD: neutrales Standard-CD (cd_fehlt).
const cdRoh = ($input.first().json || {}).cd;
const cdFehlt = !cdRoh || typeof cdRoh !== 'object';
const cd = cdFehlt ? {
  unternehmen_id: null,
  unternehmen: null,
  schrift: 'Inter',
  farben: {
    farbe_dunkel: '#1F2933',
    farbe_text_auf_dunkel: '#FFFFFF',
    farbe_akzent: '#52606D',
    farbe_akzent_dunkel: '#323F4B',
    farbe_hell: '#F5F7FA',
    farbe_grau: '#9AA5B1',
    farbe_warnung: '#B54708'
  },
  dateien: {},
  gestaltung: {}
} : cdRoh;
const wer = cd.unternehmen ? ' (' + cd.unternehmen + ')' : '';
const werte = cd.farben || {};

const farbNamen = ['farbe_dunkel', 'farbe_text_auf_dunkel', 'farbe_akzent', 'farbe_akzent_dunkel', 'farbe_hell', 'farbe_grau', 'farbe_warnung'];
const fehler = [];
if (!cd.schrift) fehler.push('schrift fehlt');
for (const n of farbNamen) {
  if (!werte[n]) fehler.push(n + ' fehlt');
  else if (!/^#[0-9a-fA-F]{6}$/.test(werte[n])) fehler.push(n + ' ist kein Farbwert im Format #RRGGBB (' + werte[n] + ')');
}

const dateien = cd.dateien || {};
const logos = {};
for (const name of ['logo_fuer_dunkel', 'logo_fuer_hell', 'bildmarke_fuer_dunkel', 'bildmarke_fuer_hell']) {
  const d = dateien[name];
  if (typeof d === 'string' && /^data:image\/(svg\+xml|png);base64,[A-Za-z0-9+/]+={0,2}$/.test(d)) logos[name] = d;
}
if (!cdFehlt) for (const pflicht of ['logo_fuer_dunkel', 'bildmarke_fuer_dunkel', 'bildmarke_fuer_hell']) if (!logos[pflicht]) fehler.push(pflicht + ' (SVG oder PNG) fehlt');
if (fehler.length) throw new Error('Corporate Design unvollständig' + wer + ': ' + fehler.join('; '));
for (const name of ['logo_fuer_dunkel', 'logo_fuer_hell', 'bildmarke_fuer_dunkel', 'bildmarke_fuer_hell']) if (!logos[name]) logos[name] = null;

// Feine Abstufungen werden aus den Grundfarben gemischt, damit nur die Grundfarben gepflegt werden müssen.
const rgb = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));
const hex = a => '#' + a.map(v => Math.round(Math.max(0, Math.min(255, v))).toString(16).padStart(2, '0')).join('').toUpperCase();
const mische = (a, b, t) => { const x = rgb(a), y = rgb(b); return hex(x.map((v, i) => v + (y[i] - v) * t)); };
const f = {
  dunkel: werte.farbe_dunkel.toUpperCase(),
  textAufDunkel: werte.farbe_text_auf_dunkel.toUpperCase(),
  akzent: werte.farbe_akzent.toUpperCase(),
  akzentDunkel: werte.farbe_akzent_dunkel.toUpperCase(),
  hell: werte.farbe_hell.toUpperCase(),
  grau: werte.farbe_grau.toUpperCase(),
  warnung: werte.farbe_warnung.toUpperCase()
};
const abgeleitet = {
  dunkelNebentext: mische(f.textAufDunkel, f.dunkel, 0.25),
  dunkelLinie: mische(f.dunkel, f.textAufDunkel, 0.08),
  dunkelKarte: mische(f.dunkel, f.textAufDunkel, 0.04),
  dunkelKartenrand: mische(f.dunkel, f.textAufDunkel, 0.1),
  hellNebentext: mische(f.dunkel, f.hell, 0.2),
  hellLinie: mische(f.hell, f.dunkel, 0.1),
  hellKartenrand: mische(f.hell, f.dunkel, 0.06),
  akzentNebentext: mische(f.dunkel, f.akzent, 0.15),
  tabellenLinie: mische(f.hell, f.dunkel, 0.06)
};
const schrift = cd.schrift;
const fontCss = "@import url('https://fonts.googleapis.com/css2?family=" + encodeURIComponent(schrift).replace(/%20/g, '+') + ":wght@400;500;600;700;800&display=block');";
const gestaltung = Object.assign({ stile: ['dunkel', 'hell', 'akzent'], punkte: true, boegen: true, gross_icon: true, icons: true, icons_aus: [] }, cd.gestaltung || {});
return [{ json: { schrift, fontCss, farben: f, abgeleitet, logos, gestaltung, icons: {}, unternehmen_id: cdFehlt ? null : cd.unternehmen_id, unternehmen: cd.unternehmen || null, cd_fehlt: cdFehlt, t_rahmen: Date.now() } }];

// Datei-Art (ALLY 20, Ladezeit Stefan 21.10.2026): GET app/stil, app/skript, app/logo – eigene, lange zwischengespeicherte Dateien der Oberfläche.
// Öffentlich wie Manifest und Symbol: keine Sitzung, keine Daten einer Person. Nur geprüfte Werte: n = Logo-Art (zwei feste Namen), v = Fassung (8 Hex-Zeichen).
// basis: / nur, wenn traefik die Anfrage über die eigene Adresse geschickt hat (X-Oberflaeche-Basis, von traefik gesetzt und überschrieben).
const art = $('Oberflächen-Stil').isExecuted === true ? 'stil' : $('Oberflächen-Skript').isExecuted === true ? 'skript' : 'logo';
const j = $input.first().json || {};
const q = j.query || {};
const s = v => String((Array.isArray(v) ? v[0] : v) ?? '').trim();
const basis = String((j.headers || {})['x-oberflaeche-basis'] ?? '') === '/' ? '/' : '/webhook/app';
const n = art === 'logo' && ['logo_fuer_dunkel', 'bildmarke_fuer_dunkel'].includes(s(q.n)) ? s(q.n) : '';
const v = /^[0-9a-f]{8}$/.test(s(q.v)) ? s(q.v) : '';
return [{ json: { art, n, v, basis, datei: art } }];

// Datei-Auftrag (ALLY 20, Ladezeit Stefan 21.10.2026): für /stil und /skript baut ALLY 21 eine leere Seite mit neutralem CD; „Dateien einsetzen“ liefert daraus
// nur den festen Stil (ohne CD-Farben) bzw. das Skript. Keine Daten einer Person.
const A = $('Datei-Art').first().json;
return [{ json: { datei: A.art, version: 1, basis: '/',
  rahmen: { produkt: '', cd: { schrift: 'Inter', farben: { dunkel: '#1F2933', textAufDunkel: '#FFFFFF', akzent: '#52606D', akzentDunkel: '#323F4B', hell: '#F5F7FA', grau: '#9AA5B1', warnung: '#B54708' }, logos: {} },
    texte: {}, sicherheit: {}, zustand: {} },
  inhalt: { seite: { art: 'funktion', titel: '' } } } }];

// Datei-Antwort bauen (ALLY 20, Ladezeit Stefan 21.10.2026): Stil bzw. Skript (aus ALLY 21, Modus datei) oder Logo (aus der Datenbank) als Datei.
// Mit passender Fassung (?v=) ein Jahr zwischenspeichern (immutable); ohne oder mit veralteter Fassung nicht dauerhaft. Fehlt etwas: 404.
const A = $('Datei-Art').first().json;
const j = $input.first().json || {};
const fassung = t => { let x = 2166136261; for (let i = 0; i < t.length; i++) { x ^= t.charCodeAt(i); x = Math.imul(x, 16777619) >>> 0; } return x.toString(16).padStart(8, '0'); };
let status = 200, typ = '', b64 = '', aktuell = '';
if (A.art === 'logo') {
  const roh = String(j.logo || '');
  const m = /^data:(image\/(?:svg\+xml|png));base64,([A-Za-z0-9+/]+={0,2})$/.exec(roh);
  if (m) { typ = m[1]; b64 = m[2]; aktuell = fassung(roh); } else status = 404;
} else if (j.datei === A.art && typeof j.text === 'string' && j.text) {
  typ = String(j.typ || ''); b64 = Buffer.from(j.text, 'utf8').toString('base64'); aktuell = String(j.v || '');
} else status = 404;
if (status !== 200) { typ = 'text/plain; charset=utf-8'; b64 = Buffer.from('Nicht gefunden', 'utf8').toString('base64'); }
const cache = status !== 200 ? 'no-store' : A.v && A.v === aktuell ? 'public, max-age=31536000, immutable' : 'public, max-age=300';
const csp = typ.startsWith('image/') ? "default-src 'none'; style-src 'unsafe-inline'; sandbox" : "default-src 'none'";
const name = A.art === 'stil' ? 'stil.css' : A.art === 'skript' ? 'skript.js' : typ === 'image/png' ? 'logo.png' : 'logo.svg';
return [{ json: { status, typ, cache, csp }, binary: { datei: { data: b64, mimeType: typ.split(';')[0], fileName: name } } }];

// Shopify-Felder (ALLY 20, Migration 82, Stefan 22.10.2026): Felder der Aktionen sh_* (Shops und Verkaufsberichte), ergänzt „Formular lesen“, ohne es zu ändern
// (Muster wie „Felder Runde 2“). Migration 98: Inhalt mit Überleitung, Mengen und Vergleich (aus, vorzeitraum, vorjahr), Aktion sh_lauf_entfernen. Migration 100: Auswahl „zusatz“. Der Client-Schlüssel eines Shops geht NICHT in "daten" (nie in Ausführungsdaten der Datenbank-Aktion als Feld), sondern nur als
// Geheimnis $6 an shopify_ui_aktion (siehe „Aktion ausführen“). Prüfen und Rechte macht die Datenbank (shopify_ui_aktion). Alle anderen Aktionen unverändert.
const F = $input.first().json;
// Migration 86 (Stefan 22.10.2026): auch „Versand einrichten“ je Postfach (pf_versand_speichern | _pruefen | _leeren): Platz, Server, Port, Benutzer und nur die LÄNGE
// des Passworts in "daten"; das Passwort selbst liest nur „Versand-Zugang (ALLY 39)“ aus dem Formular (nie Datenbank, nie Ausführungsdaten).
// Migration 88 (Stefan 22.10.2026, 16:56): auch der Schalter „Versand erlauben“ (pf_versand_erlauben | _sperren, nur der Platz)
if (/^pf_versand_(speichern|pruefen|leeren|erlauben|sperren)$/.test(String(F.aktion || ''))) {
  const W0 = $('Aktion').isExecuted ? $('Aktion').first().json : {};
  const b0 = (W0 || {}).body || {};
  const s0 = v => String((Array.isArray(v) ? v[0] : v) ?? '').trim();
  const pw = String((Array.isArray(b0.passwort) ? b0.passwort[0] : b0.passwort) ?? '');
