// Seite als JSON (ALLY 20, Stefan 23.10.2026, 16:24: „alles im Stil der Verkaufsberichte“): Fragt die neue Web-App eine Seite mit der Kopfzeile
// X-Ally-Antwort: json an, liefert ALLY 20 statt des HTML aus dem Baukasten (ALLY 21) die Seitenbeschreibung selbst (inhalt), den Rahmen aus der Datenbank
// (wie ALLY 41) und das Corporate Design ohne Bilddaten. Die Web-App baut daraus die Seite. Inhalt und Rechte sind dieselben wie beim HTML.
const j = $input.first().json || {};
const R0 = $('Rahmen laden').first().json.r || {};
// N1 (Prüfung 23.10.2026): Rahmen nur in derselben Auswahl wie die HTML-Seite – ohne funktion (workflow_id), ohne E-Mail der Person.
const P0 = R0.person || {};
const R = { angemeldet: R0.angemeldet === true, csrf: R0.csrf || '', produkt: R0.produkt || '', texte: R0.texte || {},
  person: { name: P0.name || '', rolle_text: P0.rolle_text || '' }, kopf: R0.kopf || {}, leiste: R0.leiste || {}, zustand: R0.zustand || {},
  hinweis: R0.hinweis || null, profil_ziel: R0.profil_ziel || null };
// Startseite (B9, Stefan 29.10.2026): gilt für die Person eine andere Startseite, steht sie als startziel im Rahmen der Startseite (sonst fehlt der Eintrag)
if (/^[a-z0-9-]{1,40}$/.test(String(R0.startziel || ''))) R.startziel = String(R0.startziel);
// Plan 54: eingestellte Startseite auf jeder Seite (Haus-Symbol in der Leiste); fehlt, wenn es die Startseite selbst ist oder niemand angemeldet ist
const SS = String($('Rahmen laden').first().json.startseite || '');
if (R.angemeldet && /^[a-z0-9-]{1,40}$/.test(SS) && SS !== 'start') R.startseite = SS;
const CD = $('Corporate Design (CD 1)').first().json || {};
const L = CD.logos || {};
// Farben in derselben Form wie bei ALLY 41 (cd_daten: farbe_*), sonst fällt die Web-App auf Grau zurück (Regel-Check 23.10.2026)
const F = CD.farben || {};
const farben = CD.farben ? { farbe_dunkel: F.dunkel, farbe_text_auf_dunkel: F.textAufDunkel, farbe_akzent: F.akzent, farbe_akzent_dunkel: F.akzentDunkel, farbe_hell: F.hell, farbe_grau: F.grau, farbe_warnung: F.warnung } : null;
return [{ json: { body: { rahmen: R, cd: { schrift: CD.schrift || null, farben, logo: typeof L.logo_fuer_dunkel === 'string' && L.logo_fuer_dunkel !== '' }, inhalt: j.inhalt || null } } }];

// Projekt übernehmen (ALLY 20, Migration 136, Prüfung V5): Bei mb_neu und mb_speichern (teil = projekt) prüft ALLY 20 das Projekt in Papierkram (PK 2, Projektliste).
// N1: Papierkram wird nur abgefragt, wenn „Recht für Projekt prüfen“ Sitzung, Seite und Recht bestätigt hat; sonst ist pk.ok = false (die Datenbank lehnt dann ohnehin ab).
// Die Datenbank bekommt daten.pk = { ok, gefunden, aktiv, kunde_id, name } – Kunde und Name kommen aus Papierkram, nie aus dem Browser
// („Felder Runde 2“ baut daten nur aus erlaubten Feldern, ein pk aus dem Browser gibt es dort nicht). monatsbericht_ui_aktion vergleicht kunde_id mit dem gewählten Kunden.
const F = $('Shopify-Felder').first().json;
const PK = $('Projekt laden (PK 2)').isExecuted ? ($('Projekt laden (PK 2)').first().json || {}) : {};
const liste = !PK.error && Array.isArray(PK.eintraege) ? PK.eintraege : null;
const id = String(((F.daten || {}).projekt_id) || '');
const p = liste && /^[0-9]{1,12}$/.test(id) ? liste.find(x => x && String(x.id) === id) : null;
const pk = { ok: !!liste, gefunden: !!p, aktiv: !!p && p.record_state === 'active', kunde_id: p ? String(p.company_id ?? '') : '', name: p ? String(p.name || '').slice(0, 200) : '' };
const daten = Object.assign({}, F.daten || {}, { pk });
return [{ json: Object.assign({}, F, { daten, daten_text: JSON.stringify(daten) }) }];

