-- Migration 136 (Prüfung N1): Papierkram erst abfragen, wenn Sitzung, Seite und Recht „Monatsberichte erstellen“ feststehen (nur lesen).
SELECT coalesce((SELECT NOT s.muss_pw_setzen AND ally_ui_funktion_erlaubt(s.person, s.rolle, 'monatsbericht') AND coalesce(ally_hat_recht(s.person, 'monatsbericht'), false)
  FROM ally_ui_sitzung($1::text) s), false) AS darf;

