// Abruf-Aufträge (ALLY 20, Migration 194, Stefan 01.11.2026 „Daten jetzt abrufen“): je abrufbarem Kanal des Talents den Abruf-Workflow starten wie
// ALLY 16 „Sofortabruf planen“ (dieselben Workflows, Einstieg „Sofort (Einladung)“; Storys: TALENTS 2 „Sofort (Talent-Profil)“), hier ohne Erstabruf und mit
// alle_beitraege (alle verfolgten Beiträge, auch die heute schon aktualisierten; Koordinator 01.11.2026). Die Kanäle kommen aus talents_sofortabruf_ui_aktion
// (Rechte, Sperre, Abrufgrenze geprüft). Keine Schlüssel, keine KI. Ohne gültigen Auftrag ein Eintrag ohne Workflow, damit die Antwort an die Oberfläche immer kommt.
const WF = {"instagram:taeglich": "F3XM9bJAw7sfZaj3", "instagram:woechentlich": "uZGf87ReGZtpjOGS", "instagram:stuendlich": "cWfiydJkX2zEzQQV", "facebook:taeglich": "yhWZEzG6acRQ3u0C", "threads:taeglich": "jIF2zFvSG4TJzKkv",
  "youtube:taeglich": "rlOTAsqL1fNEQ8yS", "pinterest:taeglich": "ONcCjiSJdLq2FBqF", "tiktok:taeglich": "LLnW6tl2JAgCI8OO"};
const r = (($input.first().json || {}).r || {}).r || {};
const out = [], gesehen = new Set();
for (const a of (Array.isArray(r.auftraege) ? r.auftraege : []).slice(0, 60)) {
  const id = Number(a && a.kanal_id), w = WF[String((a && a.plattform) || '') + ':' + String((a && a.art) || '')];
  if (!(Number.isInteger(id) && id > 0) || !w || !/^[A-Za-z0-9]{16}$/.test(w) || gesehen.has(w + ':' + id)) continue;
  gesehen.add(w + ':' + id);
  out.push({ json: { workflow_id: w, kanal_id: id, erstabruf: false, alle_beitraege: true } });
}
return out.length ? out : [{ json: { workflow_id: '', kanal_id: 0, erstabruf: false, alle_beitraege: false } }];

// Mediakit-Auftrag (ALLY 20, Migration 196, Plan 62): Datei aus dem Formular „Mediakit“ (POST app/datei, Feld "datei") als Auftrag „ablegen“ für TALENTS Ablage
// (Art mediakit, Talent, Name und wer aus der Datenbank, talents_mediakit_ui_aktion). Nur ein echtes PDF (beginnt mit %PDF-); sonst kein Auftrag (aktion keine) und
// ein Fehlertext für „Mediakit eintragen“. Die Ablage legt die Datei im Speicherort der Talents ab (Talents/<Talent>/Mediakits).
const r = (($('Aktion ausführen').first().json || {}).r || {}).r || {};
let bin = null;
try { const w = $('Datei').first(); const b = (w && w.binary) || {}; const k = Object.keys(b).find(x => x === 'datei') || Object.keys(b).find(x => x.startsWith('datei')); if (k) bin = { k, b: b[k] }; } catch (e) { bin = null; }
const nein = fehler => [{ json: { aktion: 'keine', vorfehler: fehler } }];
if (!bin || !/^[0-9]{1,9}$/.test(String(r.talent_id || ''))) return nein('Es ist keine Datei angekommen. Bitte erneut hochladen.');
let buf;
try { buf = await this.helpers.getBinaryDataBuffer(0, bin.k); } catch (e) { return nein('Die Datei konnte nicht gelesen werden. Bitte erneut hochladen.'); }
if (buf.subarray(0, 5).toString('latin1') !== '%PDF-') return nein('Die Datei ist kein lesbares PDF.');
const name = String(r.name || 'Mediakit.pdf');
return [{ json: { aktion: 'ablegen', talent_id: Number(r.talent_id), art: 'mediakit', name, erstellt_von: String(r.von || ''), vorfehler: '' },
  binary: { datei: await this.helpers.prepareBinaryData(buf, name, 'application/pdf') } }];
